// Volkswirtschaftslehre – erstellt aus den Lehrgangsskripten (eigene Formulierungen)
FRAGEN.push(
  // ===== Wo. 01: Wirtschaftssysteme =====
  { id: 'vwl-ws-01', fach: 'vwl', thema: 'Wirtschaftssysteme', typ: 'karte',
    frage: 'Welche drei Kernfragen muss jede Volkswirtschaft beantworten?',
    antwort: '1. WAS wird produziert? (Art und Menge der Güter)\n2. WIE wird produziert? (Einsatz von Arbeit, Kapital, Boden; Produktionsverfahren)\n3. FÜR WEN wird produziert? (Verteilung von Gütern und Einkommen)' },
  { id: 'vwl-ws-02', fach: 'vwl', thema: 'Wirtschaftssysteme', typ: 'mc',
    frage: 'Worin unterscheiden sich VWL und BWL?',
    optionen: ['VWL betrachtet die Gesamtwirtschaft, BWL das einzelne Unternehmen', 'VWL betrachtet das einzelne Unternehmen, BWL die Gesamtwirtschaft', 'VWL befasst sich nur mit dem Staatshaushalt', 'Es gibt keinen Unterschied, beide Begriffe meinen dasselbe'],
    richtig: 0,
    erklaerung: 'VWL untersucht Märkte, Staat und Konjunktur als Ganzes. BWL konzentriert sich auf das wirtschaftliche Handeln einzelner Betriebe.' },
  { id: 'vwl-ws-03', fach: 'vwl', thema: 'Wirtschaftssysteme', typ: 'karte',
    frage: 'In welche drei Teilgebiete gliedert sich die Volkswirtschaftslehre?',
    antwort: 'Wirtschaftstheorie (Mikro-, Makroökonomie, Außenwirtschaftstheorie)\nWirtschaftspolitik (Geld-, Wettbewerbs-, Sozial-, Fiskalpolitik)\nFinanzwissenschaft (Einnahmen und Ausgaben des Staates)' },
  { id: 'vwl-ws-04', fach: 'vwl', thema: 'Wirtschaftssysteme', typ: 'mc',
    frage: '„Warum steigt der Brotpreis beim Bäcker?“ – Mit welchem Teilgebiet untersucht man diese Frage?',
    optionen: ['Mikroökonomie', 'Makroökonomie', 'Finanzwissenschaft', 'Außenwirtschaftstheorie'],
    richtig: 0,
    erklaerung: 'Die Mikroökonomie betrachtet einzelne Haushalte, Unternehmen und Märkte. Die Makroökonomie dagegen gesamtwirtschaftliche Größen wie BIP oder Inflation.' },
  { id: 'vwl-ws-05', fach: 'vwl', thema: 'Wirtschaftspolitik', typ: 'mc',
    frage: 'Der Staat investiert während einer Rezession verstärkt in Straßen und Schienen. Welcher Politikbereich ist das?',
    optionen: ['Fiskalpolitik', 'Geldpolitik', 'Wettbewerbspolitik', 'Sozialpolitik'],
    richtig: 0,
    erklaerung: 'Fiskalpolitik steuert die Wirtschaft über staatliche Einnahmen und Ausgaben. Geldpolitik (Zinsen, Geldmenge) ist Aufgabe der Zentralbank, z. B. der EZB.' },
  { id: 'vwl-ws-06', fach: 'vwl', thema: 'Wirtschaftspolitik', typ: 'karte',
    frage: 'Wer betreibt Geldpolitik, mit welchen Mitteln und mit welchem Hauptziel?',
    antwort: 'Die Zentralbank (im Euroraum die EZB).\nMittel: Steuerung von Geldmenge und Leitzinsen.\nHauptziel: Preisstabilität bzw. Inflationsbekämpfung.' },
  { id: 'vwl-ws-07', fach: 'vwl', thema: 'Güter', typ: 'karte',
    frage: 'Was unterscheidet freie Güter von Wirtschaftsgütern?',
    antwort: 'Freie Güter sind unbegrenzt verfügbar und nicht knapp, z. B. Luft. Sie haben keinen Preis.\nWirtschaftsgüter sind knapp und deshalb wirtschaftlich relevant. Sie werden bewirtschaftet und haben einen Preis.' },
  { id: 'vwl-ws-08', fach: 'vwl', thema: 'Güter', typ: 'mc',
    frage: 'Eine Fräsmaschine in einem Industriebetrieb ist ein …',
    optionen: ['Investitionsgut', 'Konsumgut', 'freies Gut', 'personenbezogene Dienstleistung'],
    richtig: 0,
    erklaerung: 'Investitionsgüter (Produktionsgüter) dienen der Herstellung weiterer Güter. Konsumgüter dienen der unmittelbaren Bedürfnisbefriedigung.' },
  { id: 'vwl-ws-09', fach: 'vwl', thema: 'Güter', typ: 'karte',
    frage: 'In welche drei Gruppen lassen sich Wirtschaftsgüter einteilen?',
    antwort: 'Sachgüter (materiell; unterteilt in Investitions- und Konsumgüter)\nDienstleistungen (immateriell; sachbezogen, z. B. Reparatur, oder personenbezogen, z. B. Beratung)\nRechte (z. B. Patente, Lizenzen)' },
  { id: 'vwl-ws-10', fach: 'vwl', thema: 'Ökonomisches Prinzip', typ: 'mc',
    frage: 'Ein Unternehmen will mit einem festen Werbebudget von 50.000 € möglichst viele Neukunden gewinnen. Welches Prinzip ist das?',
    optionen: ['Maximalprinzip', 'Minimalprinzip', 'Optimumprinzip', 'Bedarfsdeckungsprinzip'],
    richtig: 0,
    erklaerung: 'Maximalprinzip: gegebener Aufwand, größtmögliches Ergebnis. Minimalprinzip: gegebenes Ergebnis, geringstmöglicher Aufwand.' },
  { id: 'vwl-ws-11', fach: 'vwl', thema: 'Ökonomisches Prinzip', typ: 'karte',
    frage: 'Erkläre das Minimalprinzip mit einem Beispiel.',
    antwort: 'Ein festgelegtes Ziel soll mit möglichst geringem Mitteleinsatz erreicht werden.\nBeispiel: Eine bestimmte Strecke mit möglichst wenig Kraftstoff fahren.' },
  { id: 'vwl-ws-12', fach: 'vwl', thema: 'Nutzen', typ: 'karte',
    frage: 'Was besagt das 1. Gossensche Gesetz?',
    antwort: 'Gesetz vom abnehmenden Grenznutzen: Mit jeder weiteren konsumierten Einheit eines Gutes sinkt der zusätzliche Nutzen (Grenznutzen). Der Gesamtnutzen steigt bis zu einem Maximum (dort ist der Grenznutzen null) und kann danach sinken.\nBeispiel: Jedes weitere Glas Wasser stillt den Durst weniger.' },
  { id: 'vwl-ws-13', fach: 'vwl', thema: 'Nutzen', typ: 'mc',
    frage: 'Was beschreibt das 2. Gossensche Gesetz?',
    optionen: ['Das Haushaltsoptimum: Der letzte ausgegebene Euro stiftet bei allen Gütern den gleichen Nutzen', 'Den abnehmenden Grenznutzen bei steigendem Konsum eines Gutes', 'Dass die Nachfrage bei steigendem Preis sinkt', 'Dass Angebot und Nachfrage den Gleichgewichtspreis bestimmen'],
    richtig: 0,
    erklaerung: 'Gesetz vom Ausgleich der Grenznutzen: Ein Haushalt teilt sein Budget so auf, dass das Verhältnis Grenznutzen zu Preis bei allen Gütern gleich ist. So erreicht er die maximale Bedürfnisbefriedigung.' },
  { id: 'vwl-ws-14', fach: 'vwl', thema: 'Wirtschaftskreislauf', typ: 'karte',
    frage: 'Welche Annahmen gelten im Modell des einfachen Wirtschaftskreislaufs?',
    antwort: 'Nur Haushalte und Unternehmen\nGeschlossene Volkswirtschaft (kein Ausland)\nKein Staat\nKein Sparen und Investieren (gesamtes Einkommen wird konsumiert)\nStationär (kein Wachstum)\nKeine zeitlichen Verzögerungen' },
  { id: 'vwl-ws-15', fach: 'vwl', thema: 'Wirtschaftskreislauf', typ: 'mc',
    frage: 'Welche Ströme fließen im einfachen Wirtschaftskreislauf von den Haushalten zu den Unternehmen?',
    optionen: ['Konsumausgaben und Faktorleistungen (z. B. Arbeit)', 'Einkommen und Konsumgüter', 'Steuern und Subventionen', 'Kredite und Zinsen'],
    richtig: 0,
    erklaerung: 'Haushalte → Unternehmen: Arbeitsleistung (Güterstrom) und Konsumausgaben (Geldstrom). Unternehmen → Haushalte: Konsumgüter (Güterstrom) und Einkommen (Geldstrom).' },
  { id: 'vwl-ws-16', fach: 'vwl', thema: 'Wirtschaftskreislauf', typ: 'karte',
    frage: 'Welche fünf Sektoren umfasst der erweiterte Wirtschaftskreislauf?',
    antwort: 'Haushalte, Unternehmen, Staat, Banken (Vermögensänderung) und Ausland.' },
  { id: 'vwl-ws-17', fach: 'vwl', thema: 'Wirtschaftssysteme', typ: 'mc',
    frage: 'Welche Form der Marktwirtschaft hat Deutschland?',
    optionen: ['Soziale Marktwirtschaft', 'Freie Marktwirtschaft', 'Zentralverwaltungswirtschaft', 'Dezentrale Planwirtschaft'],
    richtig: 0,
    erklaerung: 'Soziale Marktwirtschaft: Markt und Wettbewerb, ergänzt durch staatliche Regulierung und sozialen Ausgleich. Beispiel für eine Zentralverwaltungswirtschaft war die UdSSR.' },
  { id: 'vwl-ws-18', fach: 'vwl', thema: 'Wirtschaftssysteme', typ: 'karte',
    frage: 'Nenne die vier Grundprinzipien der Marktwirtschaft.',
    antwort: 'Preisbildung über Angebot und Nachfrage\nPrivateigentum an Produktionsmitteln\nFreier Wettbewerb\nGewinnorientierung (Gewinnstreben als Antrieb)' },
  { id: 'vwl-ws-19', fach: 'vwl', thema: 'Wirtschaftssysteme', typ: 'mc',
    frage: 'Welches ist ein typischer NACHTEIL der Marktwirtschaft?',
    optionen: ['Marktversagen, z. B. bei öffentlichen Gütern und Umweltverschmutzung', 'Fehlende Innovationsanreize', 'Hoher Planungs- und Bürokratieaufwand', 'Konsumentenwünsche werden ignoriert'],
    richtig: 0,
    erklaerung: 'Nachteile der Marktwirtschaft: Ungleichheit, Marktversagen (öffentliche Güter, externe Effekte) und Krisenanfälligkeit. Die anderen drei Antworten sind Nachteile der Zentralverwaltungswirtschaft.' },
  { id: 'vwl-ws-20', fach: 'vwl', thema: 'Wirtschaftssysteme', typ: 'karte',
    frage: 'Nenne Vor- und Nachteile der Zentralverwaltungswirtschaft.',
    antwort: 'Vorteile: gleichmäßigere Einkommensverteilung, Planungssicherheit, Grundversorgung für alle.\nNachteile: Ineffizienz (Planungsfehler, Mangel- oder Überproduktion), fehlende Innovation, viel Bürokratie, Konsumentenwünsche werden kaum berücksichtigt.' },
  { id: 'vwl-ws-21', fach: 'vwl', thema: 'Soziale Marktwirtschaft', typ: 'karte',
    frage: 'Welche drei Merkmale kennzeichnen die soziale Marktwirtschaft?',
    antwort: 'Beschränkungen (Eigentumsrechte, Freiheit des Einzelnen, Gewinnmaximierung)\nKontrolle des Wettbewerbs (Kartellverbot, Fusionskontrolle)\nSozialpolitik (Arbeitsmarkt-, Arbeitsschutz-, Steuerpolitik)' },
  { id: 'vwl-ws-22', fach: 'vwl', thema: 'Soziale Marktwirtschaft', typ: 'mc',
    frage: 'Welches Gesetz dient vor allem der Kontrolle des Wettbewerbs, z. B. durch das Kartellverbot?',
    optionen: ['GWB – Gesetz gegen Wettbewerbsbeschränkungen', 'ArbSchG – Arbeitsschutzgesetz', 'EStG – Einkommensteuergesetz', 'SGB – Sozialgesetzbuch'],
    richtig: 0,
    erklaerung: 'Das GWB (oft „Kartellgesetz“ genannt) regelt Kartellverbot und Fusionskontrolle. Das UWG richtet sich gegen unlauteren Wettbewerb.' },
  { id: 'vwl-ws-23', fach: 'vwl', thema: 'Soziale Marktwirtschaft', typ: 'mc',
    frage: 'Konjunkturpolitik, Stabilitätspolitik und Fiskalpolitik gehören in der sozialen Marktwirtschaft zur …',
    optionen: ['Prozesspolitik', 'Ordnungspolitik', 'Strukturpolitik', 'Sozialpolitik'],
    richtig: 0,
    erklaerung: 'Prozesspolitik steuert und stabilisiert den laufenden Wirtschaftsprozess. Ordnungspolitik setzt den Rahmen (z. B. Wettbewerbs-, Eigentumsordnung), Strukturpolitik stärkt langfristige Strukturen (z. B. Infrastruktur, Regionen).' },

  // ===== Wo. 01: Volkswirtschaftliche Gesamtrechnung (VGR) =====
  { id: 'vwl-vgr-01', fach: 'vwl', thema: 'VGR', typ: 'karte',
    frage: 'Was ist die Volkswirtschaftliche Gesamtrechnung (VGR), und wozu dient sie?',
    antwort: 'Ein statistisches System, das die wirtschaftliche Aktivität eines Landes für einen Zeitraum (meist Jahr oder Quartal) in Zahlen erfasst: Produktion, Verteilung und Verwendung von Gütern.\nZweck: Wirtschaftsleistung bewerten, Zeit- und Ländervergleiche ermöglichen und eine Grundlage für wirtschaftspolitische Entscheidungen schaffen (inkl. Erfolgskontrolle staatlicher Maßnahmen).' },
  { id: 'vwl-vgr-02', fach: 'vwl', thema: 'VGR', typ: 'karte',
    frage: 'Aus welchen drei Perspektiven wird das BIP in der VGR ermittelt?',
    antwort: 'Entstehungsrechnung: In welchen Wirtschaftsbereichen entsteht das BIP?\nVerwendungsrechnung: Wofür wird es verwendet (Konsum, Investitionen, Außenbeitrag)?\nVerteilungsrechnung: Wie verteilt es sich auf Einkommensarten (Arbeitnehmerentgelt, Unternehmens- und Vermögenseinkommen)?\nAlle drei führen zum selben Ergebnis.' },
  { id: 'vwl-vgr-03', fach: 'vwl', thema: 'VGR', typ: 'karte',
    frage: 'Wie lautet das Schema der Entstehungsrechnung?',
    antwort: 'Produktionswert\n− Vorleistungen\n= Bruttowertschöpfung (zu Herstellungspreisen)\n+ Gütersteuern\n− Gütersubventionen\n= Bruttoinlandsprodukt (BIP)' },
  { id: 'vwl-vgr-04', fach: 'vwl', thema: 'VGR', typ: 'karte',
    frage: 'Wie lautet das Schema der Verwendungsrechnung?',
    antwort: 'Private Konsumausgaben\n+ Konsumausgaben des Staates\n+ Bruttoinvestitionen (inkl. Vorratsveränderungen)\n+ Exporte\n− Importe\n= Bruttoinlandsprodukt (BIP)' },
  { id: 'vwl-vgr-05', fach: 'vwl', thema: 'VGR', typ: 'mc',
    frage: 'In welcher Rechnung der VGR tauchen Exporte und Importe auf?',
    optionen: ['Verwendungsrechnung', 'Entstehungsrechnung', 'Verteilungsrechnung', 'Sparquotenrechnung'],
    richtig: 0,
    erklaerung: 'Die Verwendungsrechnung zeigt, wofür das BIP genutzt wird: privater und staatlicher Konsum, Investitionen und Außenbeitrag (Exporte − Importe).' },
  { id: 'vwl-vgr-06', fach: 'vwl', thema: 'VGR', typ: 'mc',
    frage: 'Ein Unternehmen hat einen Produktionswert von 800.000 € und bezieht Vorleistungen für 300.000 €. Wie hoch ist seine Bruttowertschöpfung?',
    optionen: ['500.000 €', '1.100.000 €', '300.000 €', '800.000 €'],
    richtig: 0,
    erklaerung: 'Bruttowertschöpfung = Produktionswert − Vorleistungen = 800.000 € − 300.000 € = 500.000 €.' },
  { id: 'vwl-vgr-07', fach: 'vwl', thema: 'VGR', typ: 'karte',
    frage: 'Wie gelangt man in der Verteilungsrechnung vom Volkseinkommen zum Bruttonationaleinkommen?',
    antwort: 'Arbeitnehmerentgelt + Unternehmens- und Vermögenseinkommen = Volkseinkommen\n+ Produktions- und Importabgaben an den Staat\n− Subventionen\n+ Abschreibungen\n= Bruttonationaleinkommen (BNE)\n− Saldo der Primäreinkommen aus der übrigen Welt\n= Bruttoinlandsprodukt' },
  { id: 'vwl-vgr-08', fach: 'vwl', thema: 'VGR', typ: 'mc',
    frage: 'Eine in Deutschland lebende Ingenieurin arbeitet für ein Jahr auf einer Baustelle in Österreich. Ihr Einkommen fließt in …',
    optionen: ['das deutsche BNE, aber nicht in das deutsche BIP', 'das deutsche BIP, aber nicht in das deutsche BNE', 'das deutsche BIP und das deutsche BNE', 'weder in das deutsche BIP noch in das deutsche BNE'],
    richtig: 0,
    erklaerung: 'BNE = Inländerkonzept (Einkommen von Inländern, egal wo erzielt). BIP = Inlandskonzept (Leistung im Inland, egal von wem). Die Leistung entsteht in Österreich, also im österreichischen BIP.' },
  { id: 'vwl-vgr-09', fach: 'vwl', thema: 'VGR', typ: 'karte',
    frage: 'Was versteht man unter dem verfügbaren Einkommen der privaten Haushalte?',
    antwort: 'Einkommen nach Abzug von Steuern und Sozialabgaben, zuzüglich staatlicher Transferleistungen (z. B. Kindergeld, Renten). Es bestimmt, wie viel die Haushalte konsumieren oder sparen können.' },
  { id: 'vwl-vgr-10', fach: 'vwl', thema: 'VGR', typ: 'karte',
    frage: 'Nenne drei Schwächen des BIP als Wohlstandsmaß.',
    antwort: 'Umweltkosten und Ressourcenverbrauch werden nicht abgezogen (z. B. steigert Kohleabbau das BIP).\nLebensqualität (Gesundheit, Bildung, Gerechtigkeit) wird nicht gemessen. Ergänzende Maße: z. B. HDI.\nSchattenwirtschaft (Schwarzarbeit, illegale Tätigkeiten) wird nicht erfasst, daher wird die Leistung unterschätzt.' },
  { id: 'vwl-vgr-11', fach: 'vwl', thema: 'VGR', typ: 'mc',
    frage: 'Die Preise steigen um 5 %, die produzierte Gütermenge bleibt gleich. Was passiert?',
    optionen: ['Das nominale BIP steigt, das reale BIP bleibt gleich', 'Das reale BIP steigt, das nominale BIP bleibt gleich', 'Nominales und reales BIP steigen um 5 %', 'Nominales und reales BIP bleiben gleich'],
    richtig: 0,
    erklaerung: 'Das nominale BIP wird zu aktuellen Preisen bewertet und steigt mit der Inflation. Das reale BIP rechnet zu Preisen eines Basisjahres und zeigt nur echtes Mengenwachstum.' },
  { id: 'vwl-vgr-12', fach: 'vwl', thema: 'Kennzahlen', typ: 'karte',
    frage: 'Wie berechnet man Lohnquote und Gewinnquote, und wie hängen sie zusammen?',
    antwort: 'Lohnquote = Arbeitnehmerentgelt ÷ Volkseinkommen × 100\nGewinnquote = Unternehmens- und Vermögenseinkommen ÷ Volkseinkommen × 100\nLohnquote + Gewinnquote = 100 %' },
  { id: 'vwl-vgr-13', fach: 'vwl', thema: 'Kennzahlen', typ: 'mc',
    frage: 'Volkseinkommen 2.000 Mrd. €, Arbeitnehmerentgelt 1.400 Mrd. €. Wie hoch ist die Gewinnquote?',
    optionen: ['30 %', '70 %', '42,9 %', '60 %'],
    richtig: 0,
    erklaerung: 'Lohnquote = 1.400 ÷ 2.000 × 100 = 70 %. Gewinnquote = 100 % − 70 % = 30 %.' },
  { id: 'vwl-vgr-14', fach: 'vwl', thema: 'Kennzahlen', typ: 'karte',
    frage: 'Was sagt eine hohe bzw. niedrige Sparquote der privaten Haushalte aus?',
    antwort: 'Sparquote = nicht konsumierter Anteil des verfügbaren Einkommens.\nHoch: Vorsicht/Unsicherheit der Haushalte (oder Mangel an Konsumgütern), weniger Konsum.\nNiedrig: großer Teil des Einkommens fließt in den Konsum.\nDie Sparquote beeinflusst die Kreditvergabemöglichkeiten der Banken und damit Investitionen.' },
  { id: 'vwl-vgr-15', fach: 'vwl', thema: 'Einkommensverteilung', typ: 'mc',
    frage: 'Wie nennt man die Einkommensverteilung NACH Steuern, Abgaben und Transferleistungen?',
    optionen: ['Sekundäre Einkommensverteilung', 'Primäre Einkommensverteilung', 'Funktionale Einkommensverteilung', 'Personelle Einkommensverteilung'],
    richtig: 0,
    erklaerung: 'Primär = Verteilung über den Markt vor staatlichen Eingriffen. Sekundär = nach der Umverteilung durch den Staat.' },
  { id: 'vwl-vgr-16', fach: 'vwl', thema: 'Einkommensverteilung', typ: 'karte',
    frage: 'Was unterscheidet die funktionale von der personellen Einkommensverteilung?',
    antwort: 'Funktional: Verteilung auf die Produktionsfaktoren (Löhne für Arbeit, Zinsen/Dividenden für Kapital, Pacht für Boden). Gemessen z. B. mit Lohn- und Gewinnquote.\nPersonell: Verteilung nach der Einkommenshöhe einzelner Personen oder Haushalte, unabhängig von der Quelle. Dargestellt in Einkommensklassen und gemessen z. B. mit Lorenzkurve und Gini-Koeffizient.' },
  { id: 'vwl-vgr-17', fach: 'vwl', thema: 'Einkommensverteilung', typ: 'karte',
    frage: 'Wie liest man eine Lorenzkurve bzw. den Gini-Koeffizienten?',
    antwort: 'X-Achse: kumulierter Bevölkerungsanteil, Y-Achse: kumulierter Einkommensanteil (jeweils 0–100 %).\nDie Diagonale ist die Linie völliger Gleichverteilung. Je weiter die Lorenzkurve davon abweicht (je größer die Fläche dazwischen), desto ungleicher die Verteilung.\nGini-Koeffizient: 0 = völlige Gleichheit, 1 = völlige Ungleichheit.\nNachteil: zeigt keine Ursachen der Ungleichheit.' },
  { id: 'vwl-vgr-18', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Nenne Gründe für eine sinkende Sparquote der privaten Haushalte.',
    antwort: 'Niedrige Zinsen machen Geldanlagen unattraktiv, also wird mehr konsumiert.\nStagnierende oder sinkende Realeinkommen: Um den Lebensstandard zu halten, fließt mehr Einkommen in den Konsum.\nUnsicherheit (Weltlage, Währung) lenkt den Blick auf kurzfristige Bedürfnisse oder auf Sachwerte wie Immobilien statt Sparkonten.' },
  { id: 'vwl-vgr-19', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Welche Auswirkungen hat ein sinkender Sparwille auf die Volkswirtschaft?',
    antwort: 'Weniger Spareinlagen bei Banken, dadurch weniger Spielraum für Kredite an Unternehmen.\nLücken in der privaten Altersvorsorge, Gefahr von Altersarmut. Der Staat muss eventuell mit Transfers einspringen.\nSteigende Preise für Sachwerte (v. a. Immobilien).\nPositiv: mehr Konsum belebt die Konjunktur, steigert Beschäftigung und Steuereinnahmen.' },
  { id: 'vwl-vgr-20', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Nenne Ursachen und volkswirtschaftliche Folgen hoher Immobilienpreise.',
    antwort: 'Ursachen: niedrige Zinsen (Flucht in Sachwerte, günstige Kredite, höhere Nachfrage) und Landflucht bzw. Zuzug in Städte.\nVolkswirtschaftliche Folgen: soziale Schere wächst (Wohneigentum für mittlere und untere Einkommen unerschwinglich), Wohnungsnot, Finanzierungsrisiken bei später steigenden Zinsen, Bauland wird als Anlage zurückgehalten.\nFolgen für ein Unternehmen: hoher Kapitalbedarf, Erweiterung am Standort schwierig (eventuell Verlagerung), teure Anmietung.' },
  { id: 'vwl-vgr-21', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Begründe, warum Niedriglöhne zu Altersarmut führen und künftige Generationen belasten können.',
    antwort: 'Altersarmut: Bei niedrigem Lohn bleibt kaum Geld für private Vorsorge. Die gesetzliche Rente richtet sich nach den Beiträgen, also nach dem Bruttolohn, und liegt dann oft unter der Grundsicherung.\nBelastung künftiger Generationen: Der Staat muss niedrige Renten aus Steuermitteln aufstocken, und die Sozialkassen brauchen wegen geringer Beiträge Zuschüsse. Beides führt zu höheren Steuern und Abgaben.' },
  // ===== Wo. 02: Kennzahlen, Marktformen, Preisbildung, Außenwert des Geldes =====
  { id: 'vwl-kmp-01', fach: 'vwl', thema: 'Kennzahlen', typ: 'karte',
    frage: 'Nenne die Formeln für Produktivität, Arbeitslosenquote und Staatsquote.',
    antwort: 'Produktivität = Bruttowertschöpfung ÷ Beschäftigte\nArbeitslosenquote = registrierte Arbeitslose ÷ Erwerbspersonen × 100\nStaatsquote = Staatsausgaben ÷ BIP × 100' },
  { id: 'vwl-kmp-02', fach: 'vwl', thema: 'Kennzahlen', typ: 'mc',
    frage: 'Wer zählt zu den Erwerbspersonen?',
    optionen: ['Erwerbstätige und Arbeitslose zusammen', 'Nur Erwerbstätige in Vollzeit', 'Alle Einwohner im Alter von 15 bis 65 Jahren', 'Nur sozialversicherungspflichtig Beschäftigte'],
    richtig: 0,
    erklaerung: 'Erwerbspersonen = Erwerbstätige (Vollzeit, Teilzeit, Selbstständige) + Arbeitslose. Sie bilden den Nenner der Arbeitslosenquote.' },
  { id: 'vwl-kmp-03', fach: 'vwl', thema: 'Kennzahlen', typ: 'mc',
    frage: '2 Mio. registrierte Arbeitslose bei 45 Mio. Erwerbspersonen. Wie hoch ist die Arbeitslosenquote (gerundet)?',
    optionen: ['4,4 %', '2,0 %', '4,7 %', '22,5 %'],
    richtig: 0,
    erklaerung: '2 ÷ 45 × 100 = 4,44 %.' },
  { id: 'vwl-kmp-04', fach: 'vwl', thema: 'Kennzahlen', typ: 'karte',
    frage: 'Was sagen Kapitalintensität und Investitionsquote aus?',
    antwort: 'Kapitalintensität = Kapitalstock ÷ Erwerbstätige. Gibt an, wie viel Kapital (Maschinen, Gebäude, Anlagen) je Arbeitskraft eingesetzt wird.\nInvestitionsquote = Bruttoinvestitionen ÷ BIP. Zeigt, wie stark eine Volkswirtschaft in ihre künftige Leistungsfähigkeit investiert. Eine niedrige Quote deutet auf Investitionszurückhaltung oder Stagnation hin.' },
  { id: 'vwl-kmp-05', fach: 'vwl', thema: 'Kennzahlen', typ: 'mc',
    frage: 'Die Lohnstückkosten steigen. Was bedeutet das?',
    optionen: ['Die Löhne steigen schneller als die Produktivität', 'Die Produktivität steigt schneller als die Löhne', 'Die Arbeitslosigkeit sinkt', 'Die Staatsquote steigt'],
    richtig: 0,
    erklaerung: 'Lohnstückkosten setzen die Arbeitskosten ins Verhältnis zur Produktion. Steigen sie, wachsen die Löhne stärker als die Produktivität, und die Wettbewerbsfähigkeit sinkt eher.' },
  { id: 'vwl-kmp-06', fach: 'vwl', thema: 'Markt', typ: 'karte',
    frage: 'Welche Funktionen erfüllt ein Markt?',
    antwort: 'Preisbildung und Allokation: Preise entstehen aus Angebot und Nachfrage, knappe Ressourcen werden effizient auf Verwendungen verteilt.\nKoordination: Anbieter und Nachfrager werden zusammengeführt.\nInformation: Preise zeigen Knappheit oder Überfluss an.' },
  { id: 'vwl-kmp-07', fach: 'vwl', thema: 'Marktformen', typ: 'mc',
    frage: 'Viele Anbieter stehen vielen Nachfragern gegenüber. Wie heißt diese Marktform?',
    optionen: ['Zweiseitiges Polypol', 'Angebotsoligopol', 'Nachfragemonopol', 'Zweiseitiges Oligopol'],
    richtig: 0,
    erklaerung: 'Polypol = viele Marktteilnehmer, niemand hat Marktmacht. Beispiele: Lebensmittel- und Kleidungsmärkte.' },
  { id: 'vwl-kmp-08', fach: 'vwl', thema: 'Marktformen', typ: 'mc',
    frage: 'Wenige Automobilhersteller beliefern sehr viele Kunden. Welche Marktform liegt vor?',
    optionen: ['Angebotsoligopol', 'Nachfrageoligopol', 'Angebotsmonopol', 'Zweiseitiges Polypol'],
    richtig: 0,
    erklaerung: 'Wenige Anbieter, viele Nachfrager = Angebotsoligopol (z. B. Automobil, Mobilfunk). Hier besteht eine erhöhte Gefahr von Kartellen.' },
  { id: 'vwl-kmp-09', fach: 'vwl', thema: 'Marktformen', typ: 'karte',
    frage: 'Nenne je ein Beispiel für Nachfrageoligopol, Nachfragemonopol, Angebotsmonopol und zweiseitiges Monopol.',
    antwort: 'Nachfrageoligopol: viele Landwirte verkaufen an wenige Großhändler.\nNachfragemonopol: der Staat als einziger Käufer von Rüstungsgütern.\nAngebotsmonopol: lokaler Wasser- oder Stromversorger.\nZweiseitiges Monopol: ein Rüstungshersteller und der Staat als einziger Abnehmer. Der Preis entsteht durch Verhandlung.' },
  { id: 'vwl-kmp-10', fach: 'vwl', thema: 'Marktformen', typ: 'karte',
    frage: 'Nenne die Merkmale eines vollkommenen Marktes.',
    antwort: 'Homogene (gleichartige) Güter\nKeine Präferenzen (räumlich, sachlich, persönlich, zeitlich)\nVollständige Markttransparenz\nSehr hohe (unendliche) Reaktionsgeschwindigkeit\nViele Anbieter und Nachfrager (Polypol), freier Marktzugang\nRational-ökonomisches Verhalten aller Teilnehmer\nBeispiel aus der Prüfung: die Börse bzw. der Aktienmarkt' },
  { id: 'vwl-kmp-11', fach: 'vwl', thema: 'Preisbildung', typ: 'karte',
    frage: 'Welche Funktionen hat der Preis in der Marktwirtschaft?',
    antwort: 'Informations- und Signalfunktion (zeigt Knappheit, löst Reaktionen aus)\nKoordinationsfunktion (stimmt Pläne von Anbietern und Nachfragern ab, Markträumung)\nSelektionsfunktion (nicht wettbewerbsfähige Anbieter scheiden aus)\nLenkungsfunktion (Produktionsfaktoren wandern zu den gefragten Gütern)\nVerteilungsfunktion (Einkommen wird über Faktorpreise wie Lohn und Zins verteilt)' },
  { id: 'vwl-kmp-12', fach: 'vwl', thema: 'Preisbildung', typ: 'mc',
    frage: 'Welche Preisart wird vom alleinigen Anbieter selbst festgesetzt?',
    optionen: ['Monopolpreis', 'Wettbewerbspreis', 'Höchstpreis', 'Mindestpreis'],
    richtig: 0,
    erklaerung: 'Wettbewerbspreis: entsteht aus Angebot und Nachfrage. Monopolpreis: vom Monopolisten gesetzt. Höchst- und Mindestpreise: staatlich gebundene Preise.' },
  { id: 'vwl-kmp-13', fach: 'vwl', thema: 'Preisbildung', typ: 'mc',
    frage: 'Der Preis liegt ÜBER dem Gleichgewichtspreis. Was passiert?',
    optionen: ['Angebotsüberhang, der Preis sinkt Richtung Gleichgewicht', 'Nachfrageüberhang, der Preis steigt weiter', 'Nachfrageüberhang, der Preis sinkt', 'Der Markt ist geräumt'],
    richtig: 0,
    erklaerung: 'Über dem Gleichgewicht wird mehr angeboten als nachgefragt (Überschuss). Anbieter senken die Preise, bis angebotene und nachgefragte Menge übereinstimmen.' },
  { id: 'vwl-kmp-14', fach: 'vwl', thema: 'Preisbildung', typ: 'mc',
    frage: 'Das Einkommen der Haushalte steigt. Was passiert mit der Nachfragekurve eines normalen Gutes?',
    optionen: ['Sie verschiebt sich nach rechts', 'Sie verschiebt sich nach links', 'Es kommt nur zu einer Bewegung entlang der Kurve', 'Die Angebotskurve verschiebt sich nach rechts'],
    richtig: 0,
    erklaerung: 'Rechtsverschiebung (mehr Nachfrage) z. B. durch steigendes Einkommen, höhere Beliebtheit, teurere Substitute, billigere Komplementärgüter, Bevölkerungswachstum oder die Erwartung steigender Preise.' },
  { id: 'vwl-kmp-15', fach: 'vwl', thema: 'Preisbildung', typ: 'karte',
    frage: 'Welche Faktoren verschieben die Angebotskurve nach rechts bzw. links?',
    antwort: 'Rechts (mehr Angebot): sinkende Produktionskosten, bessere Technologie, Subventionen, mehr Anbieter, günstige Bedingungen.\nLinks (weniger Angebot): steigende Kosten, Steuern, Naturkatastrophen, weniger Anbieter, Erwartung steigender Preise (Anbieter halten Ware zurück).' },
  { id: 'vwl-kmp-16', fach: 'vwl', thema: 'Elastizität', typ: 'mc',
    frage: 'Die Kreuzpreiselastizität zwischen Butter und Margarine ist positiv. Was folgt daraus?',
    optionen: ['Es sind Substitutionsgüter', 'Es sind Komplementärgüter', 'Die Güter haben keinen Zusammenhang', 'Beide Güter sind preisunelastisch'],
    richtig: 0,
    erklaerung: 'Positiv: Steigt der Preis des einen Gutes, wird mehr vom anderen gekauft (Substitute). Negativ: Komplementärgüter (z. B. Drucker und Patronen). Null: kein Zusammenhang.' },
  { id: 'vwl-kmp-17', fach: 'vwl', thema: 'Elastizität', typ: 'karte',
    frage: 'Prüfungsstil: Warum ist die Nachfrage nach Treibstoff eher unelastisch, die nach Äpfeln eher elastisch?',
    antwort: 'Treibstoff ist kurzfristig kaum ersetzbar und wird dringend gebraucht. Bei Preisänderungen ändert sich die Menge daher wenig (steile Nachfragekurve).\nÄpfel sind verzichtbar und leicht durch anderes Obst ersetzbar. Die Menge reagiert deshalb stark auf den Preis (flache Nachfragekurve).' },
  { id: 'vwl-kmp-18', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Der Staat legt einen Fixpreis UNTER dem Gleichgewichtspreis fest (z. B. Deutschlandticket). Welche Folgen hat das auf einem normalen Gütermarkt, und was ist beim ÖPNV anders?',
    antwort: 'Normaler Markt: Nachfrageüberhang, d. h. einige Nachfrager gehen leer aus, und es kann ein Schwarzmarkt mit höheren Preisen entstehen.\nÖPNV: Kaum jemand geht leer aus, die Busse und Bahnen werden einfach voller. Ein Schwarzmarkt entfällt.\nSubstitut Auto: Die Nachfrage sinkt. Komplement Park-and-Ride-Parkplätze: Die Nachfrage steigt, Preise lassen sich leichter erhöhen.' },
  { id: 'vwl-kmp-19', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Welche Folge hätte eine gesetzliche Mietpreisdeckelung auf das Wohnungsangebot?',
    antwort: 'Ein Mietdeckel schafft keinen neuen Wohnraum. Eher sinkt das Angebot, weil Objekte, deren Miete über dem Deckel läge, nicht mehr gebaut werden. Die Knappheit bleibt bestehen.\nBessere Ansätze: ÖPNV ins Umland ausbauen, Betriebe an den Stadtrand verlagern, Anreize zur Freigabe ungenutzten Wohnraums.' },
  { id: 'vwl-kmp-20', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'mc',
    frage: 'Die EZB kauft in großem Umfang Staatsanleihen. Wie wirkt sich das typischerweise auf den Aktienmarkt aus?',
    optionen: ['Nachfragekurve verschiebt sich nach rechts, Kurse steigen', 'Angebotskurve verschiebt sich nach rechts, Kurse fallen', 'Nachfragekurve verschiebt sich nach links, Kurse fallen', 'Keine Auswirkung auf Aktienkurse'],
    richtig: 0,
    erklaerung: 'Banken und Versicherungen erhalten mehr Liquidität und suchen nach Rendite, also nach Aktien. Die Nachfrage steigt (N₀ → N₁), Kurs und Menge steigen.' },
  { id: 'vwl-kmp-21', fach: 'vwl', thema: 'Geld', typ: 'karte',
    frage: 'Welche drei Funktionen hat Geld, und welche Geldarten gibt es?',
    antwort: 'Funktionen: Tauschmittel, Wertaufbewahrungsmittel, Recheneinheit (Wertmaßstab).\nArten: Bargeld (Münzen, Banknoten, gesetzliches Zahlungsmittel) und Buchgeld/Giralgeld (Guthaben auf Konten, bewegt durch Überweisung und Kartenzahlung).' },
  { id: 'vwl-kmp-22', fach: 'vwl', thema: 'Geld', typ: 'mc',
    frage: 'Wodurch entsteht sekundäres Buchgeld (Giralgeldschöpfung)?',
    optionen: ['Durch Kreditvergabe der Geschäftsbanken an Kunden', 'Durch Druck von Banknoten bei der EZB', 'Durch Steuereinnahmen des Staates', 'Durch Exportüberschüsse'],
    richtig: 0,
    erklaerung: 'Primäre Geldschöpfung: Die Zentralbank schafft Zentralbankgeld (z. B. durch Kredite an Banken oder Ankauf von Wertpapieren). Sekundäre Geldschöpfung: Geschäftsbanken vergeben Kredite. Über den Geldschöpfungsmultiplikator vervielfacht sich so die Geldmenge.' },
  { id: 'vwl-kmp-23', fach: 'vwl', thema: 'Außenwert', typ: 'karte',
    frage: 'Was versteht man unter dem Außenwert des Euro? Was bedeutet ein Anstieg von 1,10 auf 1,20 USD/EUR?',
    antwort: 'Der Außenwert (Wechselkurs) ist der Wert des Euro gemessen in ausländischer Währung, also wie viele US-Dollar man für einen Euro bekommt (Mengennotierung).\nVon 1,10 auf 1,20: Für einen Euro muss man jetzt 1,20 statt 1,10 USD zahlen. Der Euro wurde aufgewertet.' },
  { id: 'vwl-kmp-24', fach: 'vwl', thema: 'Außenwert', typ: 'mc',
    frage: 'Was unterscheidet flexible von festen Wechselkursen?',
    optionen: ['Flexible bilden sich am Devisenmarkt, feste werden von der Zentralbank an eine andere Währung gebunden', 'Flexible legt die Regierung jährlich fest, feste bilden sich am Markt', 'Feste Wechselkurse gibt es nur innerhalb der EU', 'Flexible Wechselkurse gelten nur für Bargeld'],
    richtig: 0,
    erklaerung: 'Flexibel (z. B. EUR/USD): Angebot und Nachfrage am Devisenmarkt. Fest: Bindung an eine andere Währung. Die Zentralbank braucht dann Devisenreserven, um den Kurs zu verteidigen.' },
  { id: 'vwl-kmp-25', fach: 'vwl', thema: 'Außenwert', typ: 'karte',
    frage: 'Nenne Ursachen für eine Aufwertung des Euro.',
    antwort: 'Steigende Exporte in Drittländer (mehr Euro-Nachfrage)\nSinkende Importe aus Drittländern\nMehr Geldanlagen und Direktinvestitionen von Ausländern im Euroraum\nHöhere Zinsen im Euroraum als im Ausland (Zinsgefälle)\nNiedrigere Inflation im Euroraum\nSpekulation auf einen steigenden Euro' },
  { id: 'vwl-kmp-26', fach: 'vwl', thema: 'Außenwert', typ: 'mc',
    frage: 'Die US-Notenbank Fed erhöht die Leitzinsen, die EZB nicht. Was passiert mit dem Euro-Kurs?',
    optionen: ['Der Euro wird tendenziell abgewertet', 'Der Euro wird tendenziell aufgewertet', 'Der Euro-Kurs bleibt unverändert', 'Der Euro wird fest an den Dollar gebunden'],
    richtig: 0,
    erklaerung: 'Durch das Zinsgefälle werden Dollar-Anlagen attraktiver. Die Nachfrage nach USD steigt, mehr Euro werden angeboten, und der Euro-Kurs sinkt.' },
  { id: 'vwl-kmp-27', fach: 'vwl', thema: 'Außenwert', typ: 'karte',
    frage: 'Welche Auswirkungen hat eine Aufwertung bzw. Abwertung der eigenen Währung?',
    antwort: 'Aufwertung: Importe und Rohstoffe werden billiger, der Inflationsdruck sinkt, die Kaufkraft im Ausland steigt. ABER Exporte werden teurer, die Wettbewerbsfähigkeit sinkt, Wachstum und Beschäftigung können zurückgehen.\nAbwertung: Exporte werden billiger, das fördert Wachstum und Beschäftigung, die Leistungsbilanz verbessert sich. ABER Importe werden teurer, die Inflation steigt (importierte Inflation).' },
  { id: 'vwl-kmp-28', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Wie wirkt eine Abwertung der eigenen Währung auf die Ziele des magischen Vierecks?',
    antwort: 'Preisniveaustabilität: ungünstig, weil Importe teurer werden.\nHoher Beschäftigungsstand: günstig, weil Exporte steigen.\nWirtschaftswachstum: günstig, weil Exporte steigen und neue Einkommen entstehen.\nAußenwirtschaftliches Gleichgewicht: meist günstig (mehr Exporte, weniger Importe). Bei unverzichtbaren Importen kann es aber umgekehrt sein.' },
  { id: 'vwl-kmp-29', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Welche Vorteile hat es für ein exportierendes Unternehmen, wenn ein Zielland (z. B. Kroatien 2023) den Euro einführt?',
    antwort: 'Kein Wechselkursrisiko mehr\nGeringere Bankgebühren bei Zahlungseingängen\nKeine Umtauschkosten (Bankmarge)\nBessere Vergleichbarkeit der Preise und Angleichung der Finanzierungskonditionen' },
  { id: 'vwl-kmp-30', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Was ist eine Deflation, warum ist sie gefährlich, und wie soll ein niedriger Leitzins dagegen wirken?',
    antwort: 'Deflation: anhaltend sinkendes Preisniveau (das EZB-Ziel von ca. 2 % wird deutlich unterschritten).\nGefahr: Haushalte verschieben Käufe in Erwartung weiter sinkender Preise. Dadurch sinken Nachfrage, Gewinne, Investitionen und Löhne, die Arbeitslosigkeit steigt. Es droht eine Abwärtsspirale (Rezession).\nNiedriger Leitzins: Banken bekommen günstiges Geld, Kredite werden billiger, Sparen wird unattraktiv. Konsum, Investitionen und Geldmenge sollen steigen, die Preise wieder anziehen.\nGrenzen: Die Kreditnachfrage ist teils gesättigt, Kapital fließt ins Ausland ab, und Krisenländer haben zu wenig Sicherheiten für Kredite.' },
  // ===== Wo. 02: Binnenwert des Geldes, Eingriffe in den Markt =====
  { id: 'vwl-bm-01', fach: 'vwl', thema: 'Geldmenge', typ: 'karte',
    frage: 'Was umfassen die Geldmengen M1, M2 und M3?',
    antwort: 'M1: Bargeld + Sichteinlagen (Girokonten), die liquideste Form.\nM2: M1 + kurzfristige Spareinlagen und Termineinlagen bis 2 Jahre.\nM3: M2 + marktfähige Finanzinstrumente (z. B. Geldmarktfonds, kurzfristige Anleihen).' },
  { id: 'vwl-bm-02', fach: 'vwl', thema: 'Geldmenge', typ: 'mc',
    frage: 'Ein Guthaben auf dem Girokonto gehört zu welcher engsten Geldmenge?',
    optionen: ['M1', 'M2', 'M3', 'Zu keiner Geldmenge'],
    richtig: 0,
    erklaerung: 'Girokontoguthaben sind Sichteinlagen und gehören damit schon zu M1 (und deshalb auch zu M2 und M3).' },
  { id: 'vwl-bm-03', fach: 'vwl', thema: 'EZB-Instrumente', typ: 'karte',
    frage: 'Welche geldpolitischen Instrumente der EZB gibt es? Ordne sie Liquiditäts- und Zinspolitik zu.',
    antwort: 'Liquiditätspolitik:\nMindestreservepolitik (Pflichtguthaben der Banken bei der Zentralbank)\nOffenmarktpolitik (Kauf/Verkauf von Wertpapieren)\nZinspolitik (ständige Fazilitäten):\nSpitzenrefinanzierungsfazilität (Banken leihen sich über Nacht Geld)\nEinlagefazilität (Banken legen über Nacht Geld an)' },
  { id: 'vwl-bm-04', fach: 'vwl', thema: 'EZB-Instrumente', typ: 'mc',
    frage: 'Die EZB erhöht den Mindestreservesatz. Was ist die Folge?',
    optionen: ['Banken können weniger Kredite vergeben, die Geldmenge sinkt', 'Banken können mehr Kredite vergeben, die Geldmenge steigt', 'Die Sparzinsen sinken', 'Der Euro wird abgewertet'],
    richtig: 0,
    erklaerung: 'Ein höherer Teil der Einlagen muss bei der Zentralbank hinterlegt werden. Das schränkt die Kreditvergabe ein (restriktive Geldpolitik).' },
  { id: 'vwl-bm-05', fach: 'vwl', thema: 'EZB-Instrumente', typ: 'mc',
    frage: 'Die EZB VERKAUFT Wertpapiere am offenen Markt. Wie wirkt das?',
    optionen: ['Dem Bankensystem wird Liquidität entzogen, die Geldmenge sinkt', 'Dem Bankensystem wird Liquidität zugeführt, die Geldmenge steigt', 'Die Mindestreserve sinkt', 'Der Spitzenrefinanzierungssatz sinkt automatisch'],
    richtig: 0,
    erklaerung: 'Banken bezahlen die Wertpapiere mit Zentralbankgeld, und dieses Geld verschwindet aus dem Umlauf. Der Kauf von Anleihen wirkt umgekehrt (expansiv).' },
  { id: 'vwl-bm-06', fach: 'vwl', thema: 'Bankensystem', typ: 'karte',
    frage: 'Wie ist das deutsche Bankensystem aufgebaut (drei Säulen)?',
    antwort: 'An der Spitze: EZB (Geldpolitik im Euroraum) und Deutsche Bundesbank (nationale Zentralbank, Teil des Eurosystems).\nDrei Säulen:\n1. Private Kreditinstitute (z. B. Deutsche Bank, Commerzbank), gewinnorientiert\n2. Öffentlich-rechtliche Institute (Sparkassen, Landesbanken), mit öffentlichem Auftrag\n3. Genossenschaftsbanken (Volks- und Raiffeisenbanken), gehören ihren Mitgliedern\nAufsicht: BaFin, Bundesbank, EZB' },
  { id: 'vwl-bm-07', fach: 'vwl', thema: 'Bankensystem', typ: 'mc',
    frage: 'Bei welcher Bankengruppe sind die Kunden zugleich Eigentümer?',
    optionen: ['Genossenschaftsbanken', 'Sparkassen', 'Private Großbanken', 'Landesbanken'],
    richtig: 0,
    erklaerung: 'Mitglieder von Volks- und Raiffeisenbanken halten Geschäftsanteile und haben Mitbestimmungsrechte. Sparkassen gehören meist den Kommunen.' },
  { id: 'vwl-bm-08', fach: 'vwl', thema: 'Inflation', typ: 'karte',
    frage: 'Was ist Inflation? Nenne die Arten nach Geschwindigkeit.',
    antwort: 'Inflation = anhaltender Anstieg des allgemeinen Preisniveaus. Die Kaufkraft des Geldes sinkt.\nSchleichend: ca. 2–3 % pro Jahr\nGaloppierend: oft zweistellig, große Unsicherheit\nHyperinflation: mehrere 100 % pro Jahr (z. B. Deutschland 1923)\nWeitere Einteilung: offen/verdeckt und nach Ursache.' },
  { id: 'vwl-bm-09', fach: 'vwl', thema: 'Inflation', typ: 'mc',
    frage: 'Ein stark steigender Ölpreis verteuert Transport und Produktion, und die Unternehmen geben das weiter. Welche Inflationsart ist das?',
    optionen: ['Kosten- bzw. angebotsinduzierte Inflation', 'Nachfrageinduzierte Inflation', 'Geldmengeninduzierte Inflation', 'Verdeckte Inflation'],
    richtig: 0,
    erklaerung: 'Steigende Produktionskosten (Rohstoffe, Energie, Löhne) werden auf die Preise überwälzt. Bei der Nachfrageinflation wächst die Nachfrage schneller als das Angebot. Bei der Geldmengeninflation wächst die Geldmenge schneller als die Gütermenge.' },
  { id: 'vwl-bm-10', fach: 'vwl', thema: 'Inflation', typ: 'karte',
    frage: 'Wie wird die Inflation gemessen (VPI und HVPI)?',
    antwort: 'Das Statistische Bundesamt stellt einen Warenkorb zusammen, der die gewichteten Verbrauchsgewohnheiten eines Durchschnittshaushalts abbildet. Er wird etwa alle 5 Jahre aktualisiert.\nDie Preise des Warenkorbs werden mit einem Basisjahr (Index = 100) verglichen, daraus ergibt sich der Verbraucherpreisindex (VPI).\nBeispiel: Warenkorb 100 € → 105 € = 5 % Inflation.\nHVPI = harmonisierter VPI für alle EU-Länder, vergleichbar und Grundlage der EZB-Politik (Ziel: nahe 2 %).' },
  { id: 'vwl-bm-11', fach: 'vwl', thema: 'Inflation', typ: 'karte',
    frage: 'Nenne Schwachstellen des Verbraucherpreisindex.',
    antwort: 'Der Warenkorb veraltet (Güter fallen weg, neue kommen hinzu).\nPreis- und Qualitätsänderungen lassen sich schwer trennen.\nGeänderte Einkaufsgewohnheiten werden nur verzögert erfasst.\nVerbraucher weichen auf günstigere Ersatzgüter aus, der feste Warenkorb bildet das nicht ab.' },
  { id: 'vwl-bm-12', fach: 'vwl', thema: 'Inflation', typ: 'mc',
    frage: 'Wer ist von hoher Inflation besonders betroffen?',
    optionen: ['Sparer und Empfänger von Transferleistungen', 'Kreditnehmer mit festem Zins', 'Eigentümer von Immobilien', 'Exportunternehmen'],
    richtig: 0,
    erklaerung: 'Ersparnisse verlieren an Wert, und Transferleistungen werden nur zeitverzögert angepasst. Ärmere Haushalte können kaum ausweichen. Kreditnehmer profitieren eher, weil die reale Schuldenlast sinkt.' },
  { id: 'vwl-bm-13', fach: 'vwl', thema: 'Inflation', typ: 'karte',
    frage: 'Wie kann Inflation bekämpft werden?',
    antwort: 'Zinserhöhung durch die Zentralbank: Kredite werden teurer, Nachfrage sinkt (wichtigstes Instrument).\nGeldmenge reduzieren: Verkauf von Anleihen (Offenmarktpolitik), höhere Mindestreserve.\nKostenkontrolle durch den Staat: Maßnahmen gegen steigende Energie- und Rohstoffpreise (gegen angebotsseitige Ursachen).' },
  { id: 'vwl-bm-14', fach: 'vwl', thema: 'Deflation', typ: 'mc',
    frage: 'Was ist ein typisches Merkmal einer Deflation?',
    optionen: ['Die reale Schuldenlast von Kreditnehmern steigt', 'Die Kaufkraft des Geldes sinkt', 'Die Umlaufgeschwindigkeit des Geldes steigt', 'Die Produktion steigt stark an'],
    richtig: 0,
    erklaerung: 'Bei sinkenden Preisen steigt der reale Wert von Schulden. Außerdem sinken Produktion und Umlaufgeschwindigkeit, und die Kaufkraft des Geldes steigt.' },
  { id: 'vwl-bm-15', fach: 'vwl', thema: 'Deflation', typ: 'karte',
    frage: 'Vergleiche die Folgen von Inflation und Deflation.',
    antwort: 'Preise: Inflation ↑ | Deflation ↓\nProduktion: ↑ | ↓\nUmlaufgeschwindigkeit des Geldes: ↑ | ↓\nRealwert des Geldes: ↓ | ↑\nVertrauen in die Währung: ↓ (Flucht in Sachwerte) | ↑\nKapitalbildung: ↓ | ↑' },
  { id: 'vwl-bm-16', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Was will die EZB mit expansiver Geldpolitik erreichen, und welche Gefahren hat sie?',
    antwort: 'Ziel: Die Refinanzierung der Banken wird billiger. Banken geben niedrigere Zinsen an Haushalte und Unternehmen weiter, Kredite für Konsum und Investitionen werden attraktiver, Sparen weniger. Geldmenge und Nachfrage steigen, die Konjunktur wird angekurbelt.\nFür ein Unternehmen: günstigere Kredite und mehr Nachfrage von investierenden Kunden.\nGefahren: Inflation durch wachsende Geldmenge, Blasen auf Aktien- und Immobilienmärkten, mangelnde Haushaltsdisziplin und steigende Staatsschulden.' },
  { id: 'vwl-bm-17', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Welche Maßnahmen kann ein exportorientiertes Unternehmen gegen einen starken Euro ergreifen?',
    antwort: 'Produktion ins Ausland (außerhalb des Euroraums) verlagern, um Kosten zu senken\nPersonalkosten senken (z. B. befristete Stellen oder Zeitarbeit nicht verlängern)\nKooperationen eingehen (gemeinsame Forschung und Entwicklung, Kosten teilen)\nMehr Kunden im Euroraum gewinnen, weil diese Aufträge nicht vom Wechselkurs abhängen' },
  { id: 'vwl-bm-18', fach: 'vwl', thema: 'Markteingriffe', typ: 'mc',
    frage: 'Was unterscheidet marktkonforme von marktkonträren Eingriffen?',
    optionen: ['Marktkonforme lassen den Preismechanismus wirken (z. B. Subventionen, Steuern), marktkonträre setzen ihn außer Kraft (z. B. Mindest- und Höchstpreise)', 'Marktkonforme sind immer verboten, marktkonträre erlaubt', 'Marktkonforme betreffen nur das Ausland', 'Es gibt keinen Unterschied'],
    richtig: 0,
    erklaerung: 'Marktkonform: Angebot oder Nachfrage werden indirekt beeinflusst, der Preis bildet sich weiter am Markt. Marktkonträr (marktinkonform): Der Staat schreibt den Preis vor, und es entsteht kein Gleichgewichtspreis mehr.' },
  { id: 'vwl-bm-19', fach: 'vwl', thema: 'Markteingriffe', typ: 'karte',
    frage: 'Welche negativen Folgen haben Mindest- und Höchstpreise?',
    antwort: 'Mindestpreis (über dem Gleichgewicht, Anbieterschutz, z. B. EU-Agrarmarkt): Angebotsüberhang, Überproduktion, Lagerkosten. Oft sind weitere Eingriffe nötig (Quoten, Flächenstilllegung).\nHöchstpreis (unter dem Gleichgewicht, soziale Ziele, z. B. Sozialmieten): Nachfrageüberhang, Schwarzmarkt, zu geringes Angebot. Oft sind zusätzlich Subventionen nötig.' },
  { id: 'vwl-bm-20', fach: 'vwl', thema: 'Markteingriffe', typ: 'karte',
    frage: 'Prüfungsstil: Warum ist der gesetzliche Mindestlohn marktkonträr, und wie wirkt er im Diagramm?',
    antwort: 'Der Mindestlohn liegt über dem Gleichgewichtslohn. Der Marktmechanismus ist außer Kraft gesetzt, weil sich kein Gleichgewichtslohn bilden kann. Es entsteht ein Angebotsüberhang an Arbeit (Arbeitsangebot > Arbeitsnachfrage).\nFolgen für Unternehmen: höhere Stückkosten und schlechtere Wettbewerbsfähigkeit. Keine Wirkung, wenn die Löhne ohnehin darüber liegen. Möglich ist aber auch mehr Konsum und Umsatz durch höhere Einkommen.' },
  { id: 'vwl-bm-21', fach: 'vwl', thema: 'Markteingriffe', typ: 'mc',
    frage: 'Eine Steuervergünstigung für Elektroautos ist eine …',
    optionen: ['indirekte Subvention', 'direkte Subvention', 'Höchstpreisregelung', 'Mindestreserve'],
    richtig: 0,
    erklaerung: 'Direkte Subvention: Geldzahlung (z. B. Krisenhilfen). Indirekte Subventionen: Steuervergünstigungen, zinsgünstige Kredite, erlassene Gebühren.' },
  { id: 'vwl-bm-22', fach: 'vwl', thema: 'Markteingriffe', typ: 'karte',
    frage: 'Prüfungsstil: Warum wird Mittelstandspolitik gefordert, und welche Maßnahmen gibt es?',
    antwort: 'Gründe: KMU kommen schwerer und teurer an Kredite als Großunternehmen und haben im Wettbewerb strukturelle Nachteile.\nMaßnahmen: bessere Finanzierung (z. B. Förderkredite), steuerliche Erleichterungen, Bürokratieabbau, Förderung von Innovationen, Unterstützung auf Auslandsmärkten.' },
  { id: 'vwl-bm-23', fach: 'vwl', thema: 'Wettbewerbsrecht', typ: 'karte',
    frage: 'Was regeln §§ 1–3 GWB?',
    antwort: '§ 1: Verbot von Vereinbarungen zwischen Unternehmen, die den Wettbewerb verhindern, einschränken oder verfälschen (Kartellverbot).\n§ 2: Freistellung, wenn Verbraucher angemessen beteiligt werden und technischer/wirtschaftlicher Fortschritt (auch Nachhaltigkeit) gefördert wird.\n§ 3: Mittelstandskartelle sind zulässig, wenn sie die Wettbewerbsfähigkeit von KMU verbessern und den Wettbewerb nicht wesentlich beeinträchtigen.' },
  { id: 'vwl-bm-24', fach: 'vwl', thema: 'Wettbewerbsrecht', typ: 'mc',
    frage: 'Ab welchem Marktanteil wird nach § 18 GWB vermutet, dass ein einzelnes Unternehmen marktbeherrschend ist?',
    optionen: ['40 %', '25 %', '50 %', '66 %'],
    richtig: 0,
    erklaerung: 'Einzelunternehmen: ab 40 %. Oligopol: bis zu 3 Unternehmen mit zusammen 50 % oder bis zu 5 Unternehmen mit zusammen zwei Dritteln Marktanteil.' },
  { id: 'vwl-bm-25', fach: 'vwl', thema: 'Wettbewerbsrecht', typ: 'karte',
    frage: 'Was verbieten §§ 19, 20 und 21 GWB?',
    antwort: '§ 19: Missbrauch einer marktbeherrschenden Stellung (z. B. unangemessene Preise oder Bedingungen, Zugang zu Netzen verweigern).\n§ 20: Missbrauch relativer Marktmacht, z. B. KMU durch Verkauf unter Einstandspreis behindern.\n§ 21: Boykottverbot (keine Aufforderung zu Liefer- oder Bezugssperren).\nZuständig sind das Bundeskartellamt und die Landeskartellbehörden (§ 48). Die Monopolkommission erstellt alle 2 Jahre ein Gutachten (§ 44).' },
  { id: 'vwl-bm-26', fach: 'vwl', thema: 'Unternehmenszusammenschlüsse', typ: 'mc',
    frage: 'Bei welchem Zusammenschluss geben die Unternehmen ihre wirtschaftliche UND rechtliche Selbstständigkeit vollständig auf?',
    optionen: ['Trust (Fusion)', 'Konzern', 'Kartell', 'Interessengemeinschaft'],
    richtig: 0,
    erklaerung: 'Konzern: einheitliche Leitung, die wirtschaftliche Selbstständigkeit geht verloren, die rechtliche bleibt. Trust: Beide gehen verloren. Kartell, Konsortium und Interessengemeinschaft: wirtschaftliche Selbstständigkeit nur teilweise aufgegeben, rechtliche bleibt.' },
  { id: 'vwl-bm-27', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil: Welche Auswirkungen haben verbotene Kartellabsprachen, und welche Aufgabe hat das Bundeskartellamt?',
    antwort: 'Wettbewerb: Verzerrung, z. B. Preisabsprachen.\nKonsumenten: Der Preismechanismus ist ausgeschaltet, Kunden zahlen zu viel.\nLieferanten: Mehr Druck auf sie, kleine Lieferanten scheiden aus (Konzentration).\nBundeskartellamt: überwacht und schützt den Wettbewerb (zentrale ordnungspolitische Aufgabe), sichert Wahlfreiheit und Vielfalt. Rechtsgrundlage ist das GWB.' },
  // ===== Wo. 02: Konjunktur, Wachstum, wirtschaftspolitische Ziele, Wirtschaftspolitik =====
  { id: 'vwl-kw-01', fach: 'vwl', thema: 'Konjunktur', typ: 'karte',
    frage: 'Nenne die vier Konjunkturphasen und ihre Merkmale.',
    antwort: 'Depression (Krise): Tiefpunkt, hohe Arbeitslosigkeit, geringe Nachfrage, Kapazitäten kaum ausgelastet.\nAufschwung (Expansion): Nachfrage und Investitionen steigen, die Arbeitslosigkeit sinkt.\nHochkonjunktur (Boom): Kapazitäten voll ausgelastet, geringe Arbeitslosigkeit, Inflationsgefahr.\nAbschwung (Rezession): Nachfrage und Investitionen sinken, die Arbeitslosigkeit steigt, Haushalte sparen mehr.' },
  { id: 'vwl-kw-02', fach: 'vwl', thema: 'Konjunktur', typ: 'mc',
    frage: 'In welcher Konjunkturphase ist die Inflationsgefahr am größten?',
    optionen: ['Hochkonjunktur (Boom)', 'Depression', 'Aufschwung', 'Rezession'],
    richtig: 0,
    erklaerung: 'Im Boom sind die Kapazitäten voll ausgelastet. Die hohe Nachfrage kann dann kaum noch mit mehr Menge bedient werden, also steigen die Preise.' },
  { id: 'vwl-kw-03', fach: 'vwl', thema: 'Konjunktur', typ: 'karte',
    frage: 'Was unterscheidet Konjunktur von Wirtschaftswachstum?',
    antwort: 'Konjunktur: kurzfristige Schwankungen des BIP in Zyklen. Einflussfaktoren sind Nachfrage, Investitionen und Beschäftigung. Ziel: Stabilisierung.\nWachstum: langfristige Zunahme des BIP (Trend). Einflussfaktoren sind Kapital, Arbeitskräfte und Technologie. Ziel: nachhaltige Steigerung der Wirtschaftsleistung.' },
  { id: 'vwl-kw-04', fach: 'vwl', thema: 'Konjunkturindikatoren', typ: 'mc',
    frage: 'Welcher ist ein typischer FRÜHindikator der Konjunktur?',
    optionen: ['Auftragseingänge', 'Arbeitslosenzahlen', 'Kapazitätsauslastung', 'Lagerbestände'],
    richtig: 0,
    erklaerung: 'Frühindikatoren zeigen die künftige Entwicklung: Auftragseingänge, ifo-Geschäftsklima, Aktienkurse, Gewinnerwartungen, geplante Investitionen. Die Arbeitslosenzahl reagiert verzögert und ist ein Spätindikator.' },
  { id: 'vwl-kw-05', fach: 'vwl', thema: 'Konjunkturindikatoren', typ: 'karte',
    frage: 'Prüfungsstil (H2021): Woran erkennt man einen Konjunkturabschwung? Nenne je drei Früh- und Präsenzindikatoren.',
    antwort: 'Frühindikatoren: Auftragseingänge gehen zurück, das ifo-Geschäftsklima verschlechtert sich, die Aktienkurse fallen, die Gewinnerwartungen sinken, Investitionen werden verschoben.\nPräsenzindikatoren: Die realen Wachstumsraten bzw. das BIP-Wachstum sinken, die Kapazitätsauslastung sinkt, die Lager füllen sich und Lieferzeiten werden kürzer, die Zahl der Kurzarbeiter steigt.' },
  { id: 'vwl-kw-06', fach: 'vwl', thema: 'Konjunktur', typ: 'karte',
    frage: 'Was besagen Multiplikator- und Akzeleratorprinzip?',
    antwort: 'Multiplikator: Zusätzliche Ausgaben (z. B. des Staates) erhöhen Einkommen, dadurch steigt der Konsum, damit die Einnahmen der Unternehmen und schließlich die Investitionen. Das BIP steigt um ein Vielfaches des ursprünglichen Impulses.\nAkzelerator: Steigende Nachfrage zwingt Unternehmen, ihre Kapazitäten zu erweitern. Die Investitionen steigen dabei überproportional zur Nachfrageänderung.\nBeide verstärken sich gegenseitig.' },
  { id: 'vwl-kw-07', fach: 'vwl', thema: 'Konjunkturpolitik', typ: 'karte',
    frage: 'Nenne Vor- und Nachteile staatlicher Konjunkturprogramme.',
    antwort: 'Vorteile: Staatsausgaben (z. B. Straßenbau) schaffen Aufträge und Jobs. Kaufprämien stützen betroffene Branchen. Steuersenkungen (z. B. Mehrwertsteuer) beleben den Konsum.\nNachteile: Wirkung kommt verzögert (Time-Lag), Staatsschulden steigen (z. B. Corona-Paket 2020), nach dem Ende kann die Nachfrage einbrechen (z. B. Automarkt nach der Abwrackprämie 2009).' },
  { id: 'vwl-kw-08', fach: 'vwl', thema: 'Konjunkturpolitik', typ: 'karte',
    frage: 'Prüfungsstil (H2021): Welche Maßnahmen umfasst expansive Fiskalpolitik im Abschwung, und warum wirken sie oft schwächer als erhofft?',
    antwort: 'Maßnahmen: Steuern befristet senken (mehr privater Konsum), mehr Staatsausgaben für Investitionsgüter, staatliche Infrastrukturprogramme, Anreize für private Investitionen (bessere Abschreibungsmöglichkeiten, Investitionszulagen).\nWirkung für Unternehmen: Das Investitionsklima verbessert sich.\nGrenzen: Investitionen hängen vor allem von den Gewinnerwartungen ab, und die sind im Abschwung pessimistisch. Schuldenfinanzierte Programme können die Zinsen erhöhen und so private Investitionen verdrängen (Crowding-out). Lange Vorlaufzeiten (Time-Lag) führen dazu, dass die Wirkung oft zu spät kommt.' },
  { id: 'vwl-kw-09', fach: 'vwl', thema: 'Konjunkturpolitik', typ: 'mc',
    frage: 'Schuldenfinanzierte Staatsausgaben treiben die Zinsen hoch, und private Investitionen gehen zurück. Wie heißt dieser Effekt?',
    optionen: ['Crowding-out-Effekt', 'Multiplikatoreffekt', 'Akzeleratoreffekt', 'Time-Lag'],
    richtig: 0,
    erklaerung: 'Beim Crowding-out verdrängt die staatliche Kreditnachfrage private Investitionen. Time-Lag bezeichnet dagegen die zeitliche Verzögerung staatlicher Maßnahmen.' },
  { id: 'vwl-kw-10', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (F2019): Wie argumentieren Gewerkschaften und Arbeitgeber in Tarifverhandlungen über den Erhalt von Arbeitsplätzen?',
    antwort: 'Gewerkschaften (Kaufkrafttheorie): Lohnerhöhungen steigern das verfügbare Einkommen. Die Konsumnachfrage steigt, damit Produktion, Kapazitätsauslastung und Investitionen. So werden Arbeitsplätze gesichert bzw. neue geschaffen.\nArbeitgeber (Kostentheorie): Lohnerhöhungen erhöhen die Lohnstückkosten. Werden sie auf die Preise überwälzt, sinken Wettbewerbsfähigkeit und Nachfrage, und Personal wird freigesetzt. Deshalb sollen Lohnsteigerungen an den Produktivitätszuwachs gekoppelt werden.' },
  { id: 'vwl-kw-11', fach: 'vwl', thema: 'Wirtschaftspolitische Ziele', typ: 'karte',
    frage: 'Prüfungsstil (H2016): Nenne die sechs Ziele des magischen Sechsecks und je eine Kennzahl zur Messung.',
    antwort: 'Preisniveaustabilität: Inflationsrate (Ziel ca. 2 %)\nHoher Beschäftigungsstand: Arbeitslosenquote\nAußenwirtschaftliches Gleichgewicht: Leistungsbilanz\nStetiges, angemessenes Wachstum: reale BIP-Wachstumsrate (ca. 2–3 % gelten als gesund)\nGerechte Einkommensverteilung: Lorenzkurve bzw. Gini-Koeffizient\nLebenswerte Umwelt: CO₂-Werte, Umweltschutzkosten, Waldschadensquote' },
  { id: 'vwl-kw-12', fach: 'vwl', thema: 'Wirtschaftspolitische Ziele', typ: 'mc',
    frage: 'Welche Ziele ergänzen das magische Viereck zum magischen Sechseck?',
    optionen: ['Umweltschutz und gerechte Einkommensverteilung', 'Staatsverschuldung und Steuergerechtigkeit', 'Vollbeschäftigung und Preisstabilität', 'Bildung und Digitalisierung'],
    richtig: 0,
    erklaerung: 'Viereck (StabG 1967): Preisstabilität, hoher Beschäftigungsstand, außenwirtschaftliches Gleichgewicht, stetiges Wachstum. Das Sechseck ergänzt lebenswerte Umwelt und gerechte Einkommensverteilung.' },
  { id: 'vwl-kw-13', fach: 'vwl', thema: 'Wirtschaftspolitische Ziele', typ: 'karte',
    frage: 'Nenne drei typische Zielkonflikte im magischen Viereck.',
    antwort: 'Wachstum vs. Preisstabilität: Starkes Wachstum und hohe Nachfrage im Boom treiben die Preise.\nVollbeschäftigung vs. Preisstabilität: Bei wenig Arbeitslosigkeit steigen die Löhne und damit die Preise.\nAußenwirtschaft vs. Wachstum: Hohe Exportüberschüsse fördern Wachstum, schaffen aber weltwirtschaftliche Ungleichgewichte.\nAußerdem: Umweltschutz vs. Wachstum, Umverteilung vs. Wachstum.' },
  { id: 'vwl-kw-14', fach: 'vwl', thema: 'Wirtschaftspolitische Ziele', typ: 'karte',
    frage: 'Prüfungsstil (H2016): Nenne zu jedem Ziel des magischen Sechsecks ein wirtschaftspolitisches Instrument.',
    antwort: 'Preisstabilität: Einnahmen- und Ausgabenpolitik (Fiskalpolitik), Geldpolitik der EZB\nBeschäftigung: aktive und passive Arbeitsmarktpolitik, Bildungspolitik\nAußenwirtschaft: Zölle, Subventionen, Handelsabkommen\nWachstum: Investitionsförderung, Förderung von Forschung und Entwicklung\nEinkommensverteilung: Steuer- und Sozialpolitik\nUmwelt: Umweltpolitik, internationale Klimaabkommen' },
  { id: 'vwl-kw-15', fach: 'vwl', thema: 'Arbeitslosigkeit', typ: 'mc',
    frage: 'Ein Bauarbeiter ist im Winter ohne Arbeit. Welche Art der Arbeitslosigkeit liegt vor?',
    optionen: ['Saisonale Arbeitslosigkeit', 'Strukturelle Arbeitslosigkeit', 'Friktionelle Arbeitslosigkeit', 'Konjunkturelle Arbeitslosigkeit'],
    richtig: 0,
    erklaerung: 'Saisonal = jahreszeitlich bedingt und wiederkehrend (Bau, Landwirtschaft, Tourismus).' },
  { id: 'vwl-kw-16', fach: 'vwl', thema: 'Arbeitslosigkeit', typ: 'mc',
    frage: 'Durch den Kohleausstieg verlieren Bergleute dauerhaft ihre Arbeit. Welche Art der Arbeitslosigkeit ist das?',
    optionen: ['Strukturelle Arbeitslosigkeit', 'Saisonale Arbeitslosigkeit', 'Friktionelle Arbeitslosigkeit', 'Versteckte Arbeitslosigkeit'],
    richtig: 0,
    erklaerung: 'Strukturell = langfristig, durch Wandel von Branchen, Bedarf oder Technologie. Sie tritt oft regional oder in bestimmten Branchen auf.' },
  { id: 'vwl-kw-17', fach: 'vwl', thema: 'Arbeitslosigkeit', typ: 'karte',
    frage: 'Beschreibe friktionelle, konjunkturelle, technologische und versteckte Arbeitslosigkeit.',
    antwort: 'Friktionell (Fluktuation): kurzfristig beim Jobwechsel (Wochen bis Monate).\nKonjunkturell: mittelfristig im Abschwung. Die Nachfrage sinkt, Produktion wird zurückgefahren, Stellen werden abgebaut.\nTechnologisch: Stellen fallen durch Automatisierung oder neue Verfahren weg.\nVersteckt: nicht in der Statistik erfasst, z. B. Personen in Weiterbildung oder im Vorruhestand.\nLangzeitarbeitslos: länger als 12 Monate.' },
  { id: 'vwl-kw-18', fach: 'vwl', thema: 'Arbeitslosigkeit', typ: 'karte',
    frage: 'Prüfungsstil (H2022): Nenne drei negative volkswirtschaftliche Folgen hoher Arbeitslosigkeit.',
    antwort: 'Sinkende Einkommen: Der private Wohlstand und der Konsum gehen zurück.\nWeniger Einzahlungen in die Rentenversicherung: größere Gefahr von Altersarmut, höhere Belastung der Sozialkassen.\nSinkende Steuereinnahmen bei steigenden Sozialausgaben.\nUnzufriedenheit und sinkendes Selbstwertgefühl gefährden den sozialen Frieden.' },
  { id: 'vwl-kw-19', fach: 'vwl', thema: 'Arbeitslosigkeit', typ: 'karte',
    frage: 'Prüfungsstil (H2022): Wie können zu hohe Lohnabschlüsse zu Personalabbau führen? Welche Maßnahmen senken Arbeitslosigkeit?',
    antwort: 'Zu hohe Löhne erhöhen die Lohnstückkosten. Unternehmen gleichen das durch Rationalisierungsinvestitionen (Maschinen statt Menschen) oder Standortverlagerung aus, dadurch wird Personal freigesetzt.\nMaßnahmen: Konjunkturprogramme (Fiskalpolitik), Arbeitsmarktpolitik (Weiterbildung, z. B. Aufstiegs-BAföG, Kurzarbeit, Vermittlung), angebotsorientierte Politik (bessere Standortbedingungen), Flexibilisierung (Teilzeit, Zeitarbeit).' },
  { id: 'vwl-kw-20', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (F2020): Nenne je zwei positive und negative Folgen hoher tariflicher Lohnabschlüsse.',
    antwort: 'Positiv: Höhere Einkommen steigern die Nachfrage und beleben die Konjunktur. Umverteilung zugunsten der Arbeitnehmer stärkt den sozialen Frieden.\nNegativ: Werden die Kosten auf die Preise überwälzt, steigen die Preise und es droht eine Lohn-Preis-Spirale. Steigen die Lohnkosten stärker als die Produktivität, steigen die Lohnstückkosten und die internationale Wettbewerbsfähigkeit sinkt.' },
  { id: 'vwl-kw-21', fach: 'vwl', thema: 'Wirtschaftspolitik', typ: 'mc',
    frage: 'Wer ist ein SEKUNDÄRER Träger der Wirtschaftspolitik (beeinflusst Entscheidungen, trifft sie aber nicht)?',
    optionen: ['Gewerkschaften', 'Europäische Zentralbank', 'Bundesländer', 'Gemeinden'],
    richtig: 0,
    erklaerung: 'Primäre Träger entscheiden: Bund, Länder, Gemeinden, EZB, Bundesbank, EU. Sekundäre Träger beeinflussen: Arbeitgeberverbände, Gewerkschaften, Parteien, Interessenverbände, IHKs.' },
  { id: 'vwl-kw-22', fach: 'vwl', thema: 'Wirtschaftspolitik', typ: 'karte',
    frage: 'Ordne zu: Ordnungs-, Prozess- und Strukturpolitik. Was gehört jeweils dazu?',
    antwort: 'Ordnungspolitik: langfristiger rechtlicher Rahmen. Dazu gehören Wettbewerbs-, Eigentums-, Währungs-, Handels-, Arbeitsmarkt-, Sozial- und Umweltpolitik.\nProzesspolitik: beeinflusst den laufenden Wirtschaftsprozess. Dazu gehören Geld-, Fiskal-, Wachstums-, Einkommens-/Steuer- und Außenhandelspolitik.\nStrukturpolitik: verändert die Zusammensetzung der Wirtschaft. Dazu gehören Infrastruktur-, Regional-, sektorale Struktur- und Bildungspolitik.' },
  { id: 'vwl-kw-23', fach: 'vwl', thema: 'Wirtschaftspolitik', typ: 'mc',
    frage: 'Welche Maßnahme passt zur ANGEBOTSorientierten Wirtschaftspolitik?',
    optionen: ['Unternehmenssteuern senken und Staatsfinanzen konsolidieren', 'Staatsausgaben auf Kredit erhöhen (Deficit Spending)', 'Konsum durch Kaufprämien ankurbeln', 'Mehrwertsteuer senken, um die Nachfrage zu stärken'],
    richtig: 0,
    erklaerung: 'Angebotsorientiert (Neoliberalismus): Die Ursache der Krise liegt auf der Angebotsseite. Gefördert werden Investitionen, die Staatsfinanzen werden konsolidiert, die Marktkräfte gestärkt. Die anderen Antworten sind nachfrageorientiert (Keynes).' },
  { id: 'vwl-kw-24', fach: 'vwl', thema: 'Wirtschaftspolitik', typ: 'karte',
    frage: 'Vergleiche nachfrage- und angebotsorientierte Wirtschaftspolitik.',
    antwort: 'Nachfrageorientiert (Keynesianismus): Arbeitslosigkeit entsteht durch zu wenig private Nachfrage. Der Markt darf nicht sich selbst überlassen werden, der Staat steuert die Nachfrage, z. B. durch Steuersenkungen und mehr Staatsausgaben.\nAngebotsorientiert (Neoliberalismus): Ursache sind Störungen auf der Angebotsseite und zu wenig Investitionen. Der Staat schafft gute Wachstums- und Ertragsbedingungen: Investitionsförderung, Haushaltskonsolidierung, Stärkung der Marktkräfte.' },
  { id: 'vwl-kw-25', fach: 'vwl', thema: 'Wirtschaftspolitik', typ: 'karte',
    frage: 'Was ist Deficit Spending? Nenne Ziele, Vorteile und Nachteile.',
    antwort: 'Der Staat erhöht in der Krise kreditfinanziert seine Ausgaben (Keynes).\nZiele: Nachfrage in der Rezession stärken, Arbeitslosigkeit verhindern, Wachstum stabilisieren.\nVorteile: Die Staatsnachfrage kurbelt die Wirtschaft an, öffentliche Investitionen schaffen Arbeitsplätze, der Multiplikatoreffekt verstärkt den Impuls.\nNachteile: langfristig höhere Staatsschulden, Inflationsgefahr, Abhängigkeit von Kreditmärkten.' },
  { id: 'vwl-kw-26', fach: 'vwl', thema: 'Sozialpolitik', typ: 'karte',
    frage: 'Welche Folgen haben steigende Sozialversicherungsbeiträge?',
    antwort: 'Haushalte: Das verfügbare Einkommen sinkt, es wird weniger konsumiert, die Steuereinnahmen sinken.\nUnternehmen: Die Lohnnebenkosten steigen, Produktion droht ins Ausland abzuwandern, im Inland gehen Arbeitsplätze verloren.\nGesamtwirtschaft: Die Konjunktur geht zurück, die Arbeitslosigkeit steigt, die Sozialausgaben steigen. Es entsteht ein Teufelskreis aus sinkenden Einnahmen und steigenden Ausgaben.' },
  { id: 'vwl-kw-27', fach: 'vwl', thema: 'Umweltpolitik', typ: 'mc',
    frage: 'Eine höhere Kfz-Steuer für Fahrzeuge mit hohen Emissionen ist welches Instrument der Umweltpolitik?',
    optionen: ['Abgaben und Steuern', 'Direkte Staatsaktivität', 'Gesetze (Ge- und Verbote)', 'Aufklärung und Appelle'],
    richtig: 0,
    erklaerung: 'Instrumente der Umweltpolitik: direkte Staatsaktivität (z. B. kommunale Kläranlagen), Aufklärung und Appelle, Abgaben und Steuern, Subventionen (z. B. Solarstrom), Gesetze (z. B. Umwelthaftungs- und Abfallrecht).' },
  // ===== Wo. 03: Europäische Union, Zahlungsbilanz, internationale Organisationen =====
  { id: 'vwl-eu-01', fach: 'vwl', thema: 'EU', typ: 'karte',
    frage: 'Welche vier Grundfreiheiten gelten im europäischen Binnenmarkt?',
    antwort: '1. Freier Warenverkehr\n2. Freier Personenverkehr\n3. Freier Dienstleistungsverkehr\n4. Freier Kapitalverkehr\nBeispiel: Ein deutsches Unternehmen verkauft ohne Zölle oder Handelsbarrieren in Frankreich.' },
  { id: 'vwl-eu-02', fach: 'vwl', thema: 'EU', typ: 'mc',
    frage: 'Welche Länder gründeten 1957 die Europäische (Wirtschafts-)Gemeinschaft?',
    optionen: ['Belgien, Deutschland, Frankreich, Italien, Luxemburg, Niederlande', 'Deutschland, Frankreich, Großbritannien, Italien, Spanien, Portugal', 'Deutschland, Österreich, Schweiz, Niederlande, Belgien, Dänemark', 'Frankreich, Italien, Spanien, Griechenland, Portugal, Irland'],
    richtig: 0,
    erklaerung: 'Die sechs Gründerstaaten (EG 6) von 1957. Später kamen hinzu: 1973 Dänemark, Irland, Vereinigtes Königreich; 1981 Griechenland; 1986 Portugal und Spanien; 1995 Finnland, Österreich, Schweden; 2004 zehn Staaten; 2007 Bulgarien und Rumänien; 2013 Kroatien. 2020 trat das Vereinigte Königreich aus, seitdem sind es 27 Mitglieder.' },
  { id: 'vwl-eu-03', fach: 'vwl', thema: 'EU', typ: 'karte',
    frage: 'Nenne die vier Konvergenzkriterien (Maastricht), die ein Land für die Euro-Einführung erfüllen muss.',
    antwort: 'Inflationsrate: höchstens 1,5 Prozentpunkte über dem Durchschnitt der drei preisstabilsten Mitgliedstaaten\nHaushaltsdefizit (Neuverschuldung): höchstens 3 % des BIP\nStaatsverschuldung (Gesamtschulden): höchstens 60 % des BIP\nWechselkursstabilität: mindestens 2 Jahre spannungsfrei im WKM II ohne Abwertung\nZusätzlich: Langfristiger Zins höchstens 2 Prozentpunkte über dem der drei preisstabilsten Länder.' },
  { id: 'vwl-eu-04', fach: 'vwl', thema: 'EU', typ: 'mc',
    frage: 'Wie hoch darf laut Maastricht-Kriterien die jährliche Neuverschuldung eines Landes höchstens sein?',
    optionen: ['3 % des BIP', '60 % des BIP', '1,5 % des BIP', '2 % des BIP'],
    richtig: 0,
    erklaerung: 'Neuverschuldung (jährliches Defizit) max. 3 %, Gesamtverschuldung max. 60 % des BIP.' },
  { id: 'vwl-eu-05', fach: 'vwl', thema: 'EU', typ: 'karte',
    frage: 'Prüfungsstil (H2022): Wie funktioniert der Wechselkursmechanismus II (WKM II)?',
    antwort: 'Der Leitkurs (Zentralparität) zwischen Landeswährung und Euro wird gemeinsam mit der EZB festgelegt. Der Tageskurs darf normalerweise um ±15 % um den Leitkurs schwanken.\nDroht der Kurs die Bandbreite zu verlassen, greifen die nationale Notenbank und die EZB ein: am unteren Interventionspunkt mit Stützungskäufen der Landeswährung, am oberen mit Devisenverkäufen.\nMindestens 2 Jahre spannungsfreie Teilnahme sind Voraussetzung für den Euro-Beitritt.' },
  { id: 'vwl-eu-06', fach: 'vwl', thema: 'EU', typ: 'karte',
    frage: 'Prüfungsstil (H2022): Welche Folgen hätte ein Euro-Beitritt (z. B. Tschechiens) für Unternehmen und die Geldpolitik des Landes?',
    antwort: 'Unternehmen: Mehr Wettbewerb mit Euroländern durch transparente Preise und Wegfall des Umtauschs. Das kann Wachstum und Beschäftigung anregen. Außerdem entfallen Wechselkursrisiken und Kurssicherungskosten.\nGeldpolitik: Das Land gibt seine geldpolitische Eigenständigkeit auf. Die EZB entscheidet für den ganzen Euroraum und nimmt keine Rücksicht auf die Lage einzelner Länder.' },
  { id: 'vwl-eu-07', fach: 'vwl', thema: 'EU', typ: 'mc',
    frage: 'Was ist der Europäische Stabilitätsmechanismus (ESM)?',
    optionen: ['Eine Art Notfallkasse, die Euroländern in Finanznot Kredite oder Bürgschaften gibt', 'Das oberste Beschlussorgan der EZB', 'Ein Vertrag über Zollfreiheit mit Drittstaaten', 'Die Kartellbehörde der EU'],
    richtig: 0,
    erklaerung: 'Der ESM mit Sitz in Luxemburg hilft überschuldeten Euroländern. Der Stabilitäts- und Wachstumspakt verpflichtet zudem alle Mitglieder zu solider Haushaltspolitik.' },
  { id: 'vwl-eu-08', fach: 'vwl', thema: 'EU', typ: 'mc',
    frage: 'Welche Art von EU-Rechtsakt gilt unmittelbar in allen Mitgliedstaaten, ohne dass er in nationales Recht umgesetzt werden muss?',
    optionen: ['Verordnung', 'Richtlinie', 'Empfehlung', 'Stellungnahme'],
    richtig: 0,
    erklaerung: 'Verordnungen gelten sofort und haben Vorrang vor nationalem Recht. Richtlinien setzen einen Rahmen und müssen fristgerecht umgesetzt werden. Empfehlungen sind nicht bindend, oft aber eine Vorstufe.' },
  { id: 'vwl-eu-09', fach: 'vwl', thema: 'EU', typ: 'karte',
    frage: 'Nenne die wichtigsten Organe der EU und ihre Rolle.',
    antwort: 'Europäischer Rat: Staats- und Regierungschefs, gibt die politische Richtung vor.\nRat der EU (Ministerrat): Fachminister, beschließt Gesetze und Haushalt (Legislative, gemeinsam mit dem Parlament).\nEU-Kommission: 27 Kommissare, schlägt Gesetze vor (Exekutive).\nEuropäisches Parlament: direkt gewählt, beschließt mit und kontrolliert.\nWeitere: Gerichtshof, Rechnungshof, Wirtschafts- und Sozialausschuss, Ausschuss der Regionen, EZB.' },
  { id: 'vwl-eu-10', fach: 'vwl', thema: 'EU', typ: 'mc',
    frage: 'Welches EU-Organ hat das Initiativrecht, schlägt also Gesetze vor?',
    optionen: ['EU-Kommission', 'Europäischer Rat', 'Europäischer Rechnungshof', 'Europäische Zentralbank'],
    richtig: 0,
    erklaerung: 'Die Kommission schlägt Gesetze vor. Rat der EU und Parlament beschließen sie gemeinsam.' },
  { id: 'vwl-eu-11', fach: 'vwl', thema: 'EU-Wettbewerbsrecht', typ: 'karte',
    frage: 'Was regelt das europäische Wettbewerbsrecht?',
    antwort: 'Kartellverbot: Absprachen, die den Handel im Binnenmarkt beeinträchtigen, sind verboten. Ausnahme: Gruppenfreistellungen, z. B. bei Lizenz- oder Franchiseverträgen.\nMissbrauchsverbot: kein Missbrauch einer marktbeherrschenden Stellung.\nFusionskontrolle: Zusammenschlüsse werden auf Vereinbarkeit mit dem Binnenmarkt geprüft.\nStaatliche Beihilfen (Subventionen) müssen bei der Kommission angemeldet und genehmigt werden.\nEU-Recht hat in der Regel Vorrang vor nationalem Recht.' },
  { id: 'vwl-eu-12', fach: 'vwl', thema: 'EZB', typ: 'karte',
    frage: 'Nenne die Aufgaben der Europäischen Zentralbank.',
    antwort: 'Geldpolitik für die Eurozone (Leitzinsen, Ziel Preisstabilität)\nOffenmarktgeschäfte (Kauf und Verkauf von Wertpapieren, Steuerung der Geldmenge)\nBankenaufsicht über systemrelevante Banken\nVerwaltung der Währungsreserven, Devisengeschäfte und Interventionen\nGenehmigung der Euro-Banknoten\nReibungslose Zahlungssysteme\nBeratung von EU-Institutionen' },
  { id: 'vwl-eu-13', fach: 'vwl', thema: 'EZB', typ: 'karte',
    frage: 'Prüfungsstil (F2021): Erkläre, warum die EZB „autonom“ ist.',
    antwort: 'Funktionell unabhängig: Sie nimmt keine Weisungen von Regierungen oder EU-Organen an.\nPersonell unabhängig: Die Mitglieder des Direktoriums werden für 8 Jahre ohne Wiederwahl ernannt, die Zentralbankpräsidenten für mindestens 5 Jahre.\nFinanziell und instrumentell unabhängig: eigenes Kapital und eigener Haushalt, eigene geldpolitische Instrumente.\nAußerdem: keine Kredite an Staaten (Verbot der Staatsfinanzierung).' },
  { id: 'vwl-eu-14', fach: 'vwl', thema: 'EZB', typ: 'mc',
    frage: 'Was unterscheidet das ESZB vom Eurosystem?',
    optionen: ['Das ESZB umfasst die EZB und alle EU-Zentralbanken, das Eurosystem nur die der Euroländer', 'Das Eurosystem umfasst alle EU-Zentralbanken, das ESZB nur die der Euroländer', 'Beide Begriffe meinen genau dasselbe', 'Das ESZB ist die Bankenaufsicht, das Eurosystem die Kartellbehörde'],
    richtig: 0,
    erklaerung: 'Nicht alle EU-Staaten haben den Euro. Das ESZB = EZB + nationale Zentralbanken aller 27 EU-Länder. Das Eurosystem = EZB + nationale Zentralbanken der Euroländer.' },
  { id: 'vwl-eu-15', fach: 'vwl', thema: 'EZB', typ: 'mc',
    frage: 'Welches EZB-Organ legt die Leitzinsen fest?',
    optionen: ['Der EZB-Rat', 'Das Direktorium', 'Der Erweiterte Rat', 'Die EU-Kommission'],
    richtig: 0,
    erklaerung: 'EZB-Rat (Direktorium + Präsidenten der Euro-Zentralbanken) = oberstes Beschlussorgan. Direktorium (6 Mitglieder) = setzt um, führt das Tagesgeschäft. Erweiterter Rat = berät, auch mit Nicht-Euro-Ländern.' },
  { id: 'vwl-eu-16', fach: 'vwl', thema: 'Protektionismus', typ: 'karte',
    frage: 'Nenne Instrumente des Protektionismus.',
    antwort: 'Offen: Zölle (verteuern Importe), Importquoten (Mengengrenzen), Subventionen für heimische Unternehmen.\nVersteckt: technische Handelshemmnisse (Normen, Sicherheits- und Umweltvorschriften), Währungsmanipulation (Abwertung macht Exporte billiger, Importe teurer), Exportförderung (Steuererleichterungen, Förderprogramme).' },
  { id: 'vwl-eu-17', fach: 'vwl', thema: 'Protektionismus', typ: 'karte',
    frage: 'Nenne Vor- und Nachteile von Protektionismus im Vergleich zum Freihandel.',
    antwort: 'Vorteile: Schutz heimischer Unternehmen und Arbeitsplätze, Unabhängigkeit in strategischen Branchen (Energie, Technologie), Schutz vor Dumping, geringeres Handelsdefizit.\nNachteile: teurere Importe, weniger Auswahl, Gefahr von Handelskonflikten und Vergeltungszöllen, gebremste Innovation und gebremstes Wachstum.\nFreihandel: günstigere Preise und mehr Innovation durch globale Konkurrenz.' },
  { id: 'vwl-eu-18', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2024): Nenne drei EU-Sanktionen gegen Russland und ihre Auswirkungen auf ein Industrieunternehmen.',
    antwort: 'Einreiseverbot für russische Transportunternehmen (und keine westlichen Speditionen mehr nach Russland): Waren können weder bezogen noch ausgeliefert werden.\nAusschluss russischer Banken aus SWIFT: Zahlungen sind kaum noch möglich, Umwege sind teuer, offene Forderungen werden nicht beglichen.\nLuftraumsperre: Kundenpflege und Service vor Ort sind praktisch unmöglich.\nÖlembargo bzw. Preisdeckel: weltweite Verknappung, höhere Energie- und Kraftstoffpreise, also höhere Verkaufspreise oder geringere Marge.' },
  { id: 'vwl-eu-19', fach: 'vwl', thema: 'Zahlungsbilanz', typ: 'karte',
    frage: 'Was ist die Zahlungsbilanz, und aus welchen Teilbilanzen besteht sie?',
    antwort: 'Systematische Aufzeichnung aller wirtschaftlichen Transaktionen eines Landes mit dem Ausland in einem Zeitraum.\nA. Leistungsbilanz: Handelsbilanz (Waren), Dienstleistungsbilanz, Bilanz der Erwerbs- und Vermögenseinkommen (Primäreinkommen), Übertragungsbilanz (Sekundäreinkommen)\nB. Bilanz der Vermögensübertragungen (z. B. Schenkungen, Erbschaften)\nC. Kapitalbilanz (z. B. Direktinvestitionen, Wertpapiere)\nD. Devisenbilanz (Veränderung der Gold- und Devisenreserven)\nE. Restposten (statistische Differenzen)' },
  { id: 'vwl-eu-20', fach: 'vwl', thema: 'Zahlungsbilanz', typ: 'mc',
    frage: 'Deutsche Touristen geben im Urlaub in Spanien Geld aus. In welcher Teilbilanz der deutschen Zahlungsbilanz wird das erfasst?',
    optionen: ['Dienstleistungsbilanz (Passivseite, Import)', 'Handelsbilanz (Aktivseite, Export)', 'Kapitalbilanz', 'Übertragungsbilanz'],
    richtig: 0,
    erklaerung: 'Reiseverkehr zählt zu den Dienstleistungen. Ausgaben im Ausland sind Dienstleistungsimporte, also ein Geldabfluss.' },
  { id: 'vwl-eu-21', fach: 'vwl', thema: 'Zahlungsbilanz', typ: 'mc',
    frage: 'Deutschland zahlt Beiträge an die EU und die UN. Wo wird das erfasst?',
    optionen: ['Übertragungsbilanz', 'Handelsbilanz', 'Devisenbilanz', 'Bilanz der Erwerbs- und Vermögenseinkommen'],
    richtig: 0,
    erklaerung: 'Unentgeltliche laufende Leistungen ohne Gegenleistung (z. B. Beiträge an internationale Organisationen, Entwicklungshilfe, Überweisungen von Gastarbeitern) gehören zur Übertragungsbilanz.' },
  { id: 'vwl-eu-22', fach: 'vwl', thema: 'Zahlungsbilanz', typ: 'mc',
    frage: 'Ein US-Unternehmen baut eine Fabrik in Deutschland. Wo erscheint das in der deutschen Zahlungsbilanz?',
    optionen: ['Kapitalbilanz (Direktinvestition von Ausländern im Inland)', 'Handelsbilanz', 'Dienstleistungsbilanz', 'Übertragungsbilanz'],
    richtig: 0,
    erklaerung: 'Grenzüberschreitende Kapitalflüsse wie Direktinvestitionen und Wertpapierkäufe stehen in der Kapital(verkehrs)bilanz.' },
  { id: 'vwl-eu-23', fach: 'vwl', thema: 'Zahlungsbilanz', typ: 'karte',
    frage: 'Was zeigt die Devisenbilanz, und wie hängt sie mit den anderen Teilbilanzen zusammen?',
    antwort: 'Sie zeigt die Veränderung der Gold- und Devisenreserven der Zentralbank, z. B. wenn die EZB Dollar kauft oder verkauft, um den Euro-Kurs zu stabilisieren.\nSie gleicht die Salden von Leistungs- und Kapitalbilanz aus. Die Zahlungsbilanz insgesamt ist deshalb immer ausgeglichen. Statistische Differenzen stehen im Restposten.' },
  { id: 'vwl-eu-24', fach: 'vwl', thema: 'Internationale Organisationen', typ: 'karte',
    frage: 'Prüfungsstil (H2020): Erläutere die WTO, ihre Finanzierung und drei Grundprinzipien.',
    antwort: 'Welthandelsorganisation, gegründet 1995, Sitz in Genf. Dach für die Abkommen GATT (Waren), GATS (Dienstleistungen) und TRIPS (geistiges Eigentum). Die Mitglieder decken etwa 98 % des Welthandels ab. Ziel: Handel fördern und dadurch den Lebensstandard erhöhen.\nFinanzierung: Mitgliedsbeiträge, abhängig vom Anteil des Landes am Welthandel.\nGrundprinzipien: Meistbegünstigung, Inländerbehandlung bzw. Nichtdiskriminierung, Transparenz (außerdem Liberalisierung und Reziprozität).' },
  { id: 'vwl-eu-25', fach: 'vwl', thema: 'Internationale Organisationen', typ: 'mc',
    frage: 'Was besagt das Meistbegünstigungsprinzip der WTO?',
    optionen: ['Handelsvorteile, die ein Land einem Partner gewährt, müssen allen Mitgliedern gewährt werden', 'Inländische und ausländische Anbieter müssen gleich behandelt werden', 'Handelsregeln müssen veröffentlicht werden', 'Wer Erleichterungen erhält, soll selbst welche gewähren'],
    richtig: 0,
    erklaerung: 'Die anderen Antworten beschreiben Inländerbehandlung (Nichtdiskriminierung), Transparenz und Reziprozität.' },
  { id: 'vwl-eu-26', fach: 'vwl', thema: 'Internationale Organisationen', typ: 'karte',
    frage: 'Warum verliert die WTO im Welthandel an Bedeutung?',
    antwort: 'Die USA haben ihre Mitarbeit (u. a. im Streitschlichtungsverfahren) eingeschränkt.\nDas Regelwerk wurde nicht an neue Themen angepasst, z. B. geistiges Eigentum oder Nachhaltigkeit.\nBilaterale Abkommen gelten als effektiver, z. B. CETA mit Kanada oder TPP11 in Asien.' },
  { id: 'vwl-eu-27', fach: 'vwl', thema: 'Internationale Organisationen', typ: 'mc',
    frage: 'Welche Organisation vergibt Kredite an Staaten mit Zahlungsproblemen und knüpft sie meist an Reformauflagen?',
    optionen: ['Internationaler Währungsfonds (IWF)', 'WTO', 'OECD', 'Europäischer Rechnungshof'],
    richtig: 0,
    erklaerung: 'Der IWF (190 Mitglieder) sichert die globale Finanzstabilität. Die OECD fördert Wachstum, Wohlstand und Zusammenarbeit durch Analysen und Empfehlungen. Die WTO regelt den Welthandel.' },
  // ===== Wo. 03: Rechtsformen, Unternehmenszusammenschlüsse, Standortwahl =====
  { id: 'vwl-rf-01', fach: 'vwl', thema: 'Rechtsformen', typ: 'karte',
    frage: 'Nach welchen Kriterien wählt man eine Rechtsform?',
    antwort: 'Haftung und Kapital: Haftungsumfang, Eigenkapitalausstattung, Finanzierungsmöglichkeiten\nFührung und Kontrolle: Leitungsbefugnis, Aufsicht, Mitbestimmung\nGewinn und Kosten: Gewinn- und Verlustbeteiligung, Entnahmerechte, Steuerbelastung\nFormalitäten: Publizitätspflicht, Gründungs- und Kapitalerhöhungskosten' },
  { id: 'vwl-rf-02', fach: 'vwl', thema: 'Rechtsformen', typ: 'karte',
    frage: 'Wann müssen Personengesellschaften ihren Jahresabschluss veröffentlichen, wann Kapitalgesellschaften?',
    antwort: 'Kapitalgesellschaften: immer, unabhängig von der Größe (Bundesanzeiger, innerhalb von 12 Monaten nach dem Bilanzstichtag).\nPersonengesellschaften: nur, wenn sie besonders groß sind (§ 1 PublG), d. h. mindestens 2 von 3 Schwellen überschreiten: Bilanzsumme > 65 Mio. €, Umsatz > 130 Mio. €, > 5.000 Beschäftigte.' },
  { id: 'vwl-rf-03', fach: 'vwl', thema: 'Rechtsformen', typ: 'mc',
    frage: 'Wie wird der Gewinn einer OHG verteilt, wenn im Gesellschaftsvertrag nichts geregelt ist?',
    optionen: ['4 % auf den Kapitalanteil, der Rest nach Köpfen', 'Komplett nach Köpfen', 'Komplett nach Kapitalanteilen', 'Der Geschäftsführer erhält den gesamten Gewinn'],
    richtig: 0,
    erklaerung: 'Gesetzliche Regel bei der OHG: 4 % Verzinsung des Kapitalanteils, der Rest nach Köpfen. Verluste werden nach Köpfen verteilt.' },
  { id: 'vwl-rf-04', fach: 'vwl', thema: 'Rechtsformen', typ: 'karte',
    frage: 'Was unterscheidet Komplementär und Kommanditist in einer KG?',
    antwort: 'Komplementär (Vollhafter): haftet unbeschränkt mit Privat- und Gesellschaftsvermögen und führt allein die Geschäfte.\nKommanditist (Teilhafter): haftet nur mit seiner Einlage, ist von der Geschäftsführung ausgeschlossen und hat nur Kontroll- und Widerspruchsrechte.\nGewinn: oft 4 % auf die Einlage, der Rest im angemessenen Verhältnis bzw. nach Vertrag.' },
  { id: 'vwl-rf-05', fach: 'vwl', thema: 'Rechtsformen', typ: 'mc',
    frage: 'Ein Unternehmer braucht Kapital, will aber nach außen allein auftreten und keine Mitsprache abgeben. Welche Form passt am besten?',
    optionen: ['Stille Gesellschaft', 'OHG', 'GbR', 'AG'],
    richtig: 0,
    erklaerung: 'Der stille Gesellschafter tritt nach außen nicht auf, hat keine Mitsprache in der Geschäftsführung und haftet nur mit seiner Einlage. Der Unternehmer haftet unbeschränkt.' },
  { id: 'vwl-rf-06', fach: 'vwl', thema: 'Rechtsformen', typ: 'mc',
    frage: 'Welches Mindestkapital braucht eine GmbH, und wie viel muss bei der Gründung eingezahlt sein?',
    optionen: ['25.000 € Stammkapital, mindestens 12.500 € eingezahlt', '50.000 € Grundkapital, vollständig eingezahlt', '1 € Stammkapital', 'Kein Mindestkapital'],
    richtig: 0,
    erklaerung: 'GmbH: 25.000 € Stammkapital, mindestens 12.500 € bei Gründung. AG und KGaA: 50.000 € Grundkapital. UG: ab 1 €. SE: 120.000 €.' },
  { id: 'vwl-rf-07', fach: 'vwl', thema: 'Rechtsformen', typ: 'karte',
    frage: 'Welche Organe hat eine GmbH, und wann ist ein Aufsichtsrat Pflicht?',
    antwort: 'Geschäftsführer (Pflicht): führt die Geschäfte, vertritt die GmbH nach außen und wird von der Gesellschafterversammlung bestellt. Er muss kein Gesellschafter sein und haftet bei Pflichtverletzungen persönlich.\nGesellschafterversammlung (Pflicht): oberstes Organ. Stimmrecht nach Geschäftsanteilen. Bestellt und beruft Geschäftsführer ab, entscheidet über Satzungsänderungen und Gewinnverwendung, genehmigt den Jahresabschluss.\nAufsichtsrat: erst ab mehr als 500 Mitarbeitern Pflicht, sonst freiwillig. Er überwacht und berät, führt aber nicht.' },
  { id: 'vwl-rf-08', fach: 'vwl', thema: 'Rechtsformen', typ: 'karte',
    frage: 'Was ist die Ansparpflicht der UG (haftungsbeschränkt)?',
    antwort: 'Die UG muss jedes Jahr 25 % ihres Jahresüberschusses in eine Rücklage einstellen, bis 25.000 € erreicht sind. Danach kann sie in eine GmbH umgewandelt werden.\nNachteil: Die Ansparpflicht schränkt die Liquidität ein. Für schnelles Wachstum ist die UG deshalb weniger geeignet.' },
  { id: 'vwl-rf-09', fach: 'vwl', thema: 'Rechtsformen', typ: 'mc',
    frage: 'Wer bestellt den Vorstand einer AG?',
    optionen: ['Der Aufsichtsrat', 'Die Hauptversammlung', 'Die Aktionäre per Briefwahl', 'Das Handelsregister'],
    richtig: 0,
    erklaerung: 'Der Aufsichtsrat bestellt den Vorstand für höchstens 5 Jahre (Verlängerung möglich), kontrolliert ihn und kann ihn abberufen. Die Hauptversammlung wählt die Anteilseignervertreter im Aufsichtsrat.' },
  { id: 'vwl-rf-10', fach: 'vwl', thema: 'Rechtsformen', typ: 'karte',
    frage: 'Nenne die drei Organe der AG und ihre Aufgaben.',
    antwort: 'Vorstand: führt die Geschäfte eigenverantwortlich, vertritt die AG nach außen, erstellt Jahresabschluss und Lagebericht, berichtet an den Aufsichtsrat.\nAufsichtsrat: bestellt, überwacht und beruft den Vorstand ab, prüft den Jahresabschluss, stimmt Großinvestitionen zu.\nHauptversammlung: wählt die Aufsichtsratsmitglieder der Anteilseignerseite, beschließt über Gewinnverwendung (Dividende), Kapitalmaßnahmen und Satzungsänderungen, entlastet Vorstand und Aufsichtsrat. Ins operative Geschäft mischt sie sich nicht ein.' },
  { id: 'vwl-rf-11', fach: 'vwl', thema: 'Mitbestimmung', typ: 'mc',
    frage: 'Eine AG hat 2.500 Mitarbeiter. Wie hoch ist der Anteil der Arbeitnehmervertreter im Aufsichtsrat?',
    optionen: ['50 %', 'Ein Drittel', '25 %', 'Keine Arbeitnehmervertreter'],
    richtig: 0,
    erklaerung: 'Ab 500 Mitarbeitern: ein Drittel Arbeitnehmervertreter. Ab 2.000 Mitarbeitern: 50 % (Mitbestimmungsgesetz).' },
  { id: 'vwl-rf-12', fach: 'vwl', thema: 'Rechtsformen', typ: 'karte',
    frage: 'Was ist eine KGaA, und für wen eignet sie sich?',
    antwort: 'Mischform aus KG und AG: mindestens ein Komplementär (haftet unbeschränkt, führt allein die Geschäfte) und Kommanditaktionäre (haften nur mit ihren Aktien, haben Kontrollrechte über die Hauptversammlung). Mindestgrundkapital 50.000 €.\nGeeignet z. B. für Familienunternehmen, die Kapital über die Börse aufnehmen wollen, ohne die Kontrolle abzugeben.' },
  { id: 'vwl-rf-13', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2021): Beschreibe die GmbH & Co. KG anhand von drei Kriterien und nenne je einen Vor- und Nachteil.',
    antwort: 'Kriterien:\nEine KG, deren Komplementär eine GmbH ist. Dadurch ist die Haftung des Vollhafters praktisch beschränkt.\nDie Firma muss den Zusatz „GmbH & Co. KG“ tragen (Hinweis auf beschränkte Haftung).\nDie GmbH muss keine Kapitaleinlage leisten. Die Geschäftsführung übernimmt der GmbH-Geschäftsführer.\nEs handelt sich um eine Personengesellschaft.\nVorteil: Haftungsbeschränkung durch die GmbH, die Geschäftsführung liegt allein bei der GmbH.\nNachteil: hoher Buchführungsaufwand (zwei Gesellschaften), eingeschränkte Kreditwürdigkeit, weil keine natürliche Person unbeschränkt haftet.' },
  { id: 'vwl-rf-14', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (F2022): Ein Gründer schwankt zwischen OHG und GmbH. Welche Auswirkungen haben die beiden Rechtsformen für ihn?',
    antwort: 'OHG: Er muss Mitgesellschaftern Mitsprache einräumen, weil sie direkt, solidarisch und voll haften. Er muss den Gewinn teilen und trägt das Risiko für Fehlentscheidungen anderer Gesellschafter mit.\nGmbH: höherer Gründungs- und Verwaltungsaufwand, Haftung in der Regel auf das Gesellschaftsvermögen begrenzt, steuerlich höhere Belastung der Gesellschafter.\nBei weiterem Wachstum: Umwandlung in eine AG (mehr Möglichkeiten der Kapitalbeschaffung) bzw. bei EU-weitem Engagement in eine SE (hohes internationales Ansehen).' },
  { id: 'vwl-rf-15', fach: 'vwl', thema: 'Rechtsformen', typ: 'mc',
    frage: 'Welche Rechtsform ermöglicht eine einfache Sitzverlegung innerhalb der EU und hat ein Mindestkapital von 120.000 €?',
    optionen: ['SE (Europäische Aktiengesellschaft)', 'KGaA', 'GmbH & Co. KG', 'Genossenschaft'],
    richtig: 0,
    erklaerung: 'Die SE basiert auf EU-Recht. Sie kann zwischen monistischem System (Verwaltungsrat) und dualistischem System (Vorstand und Aufsichtsrat) wählen. Besteuert wird nach nationalem Recht des Sitzlandes.' },
  { id: 'vwl-rf-16', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2018): Vergleiche OHG, KG, GmbH und AG nach Kapitalausstattung, Geschäftsführung und Haftung.',
    antwort: 'OHG: kein Mindestkapital, Geschäftsführung durch alle Gesellschafter, alle haften mit Geschäfts- und Privatvermögen.\nKG: kein Mindestkapital, Geschäftsführung durch die Komplementäre. Komplementäre haften voll, Kommanditisten mit der (ausstehenden) Einlage.\nGmbH: 25.000 €, Geschäftsführer, Haftung mit dem Gesellschaftsvermögen.\nAG: 50.000 €, Vorstand, Haftung mit dem Gesellschaftsvermögen.' },
  { id: 'vwl-rf-17', fach: 'vwl', thema: 'Unternehmenszusammenschlüsse', typ: 'mc',
    frage: 'Ein Automobilhersteller schließt sich mit seinem Reifenzulieferer zusammen. Welche Art von Zusammenschluss ist das?',
    optionen: ['Vertikal', 'Horizontal', 'Konglomerat (diagonal)', 'Kartell'],
    richtig: 0,
    erklaerung: 'Vertikal = verschiedene Produktionsstufen (Hersteller und Zulieferer). Horizontal = gleiche Stufe (zwei Autohersteller). Konglomerat = branchenfremd (Diversifikation, Risikostreuung).' },
  { id: 'vwl-rf-18', fach: 'vwl', thema: 'Unternehmenszusammenschlüsse', typ: 'karte',
    frage: 'Was unterscheidet Kooperation und Konzentration? Ordne Joint Venture, strategische Allianz, Konzern, Holding, Fusion und Franchise zu.',
    antwort: 'Kooperation: Die Unternehmen bleiben rechtlich und wirtschaftlich selbstständig. Dazu gehören strategische Allianz, Kartell, Franchise und Joint Venture (gemeinsames, neues Tochterunternehmen).\nKonzentration: Die wirtschaftliche (Konzern, Holding, Übernahme) bzw. auch die rechtliche Selbstständigkeit (Fusion) wird aufgegeben. Beim Konzern bleibt die Tochter rechtlich selbstständig, die Fusion bildet eine neue rechtliche Einheit.' },
  { id: 'vwl-rf-19', fach: 'vwl', thema: 'Unternehmenszusammenschlüsse', typ: 'karte',
    frage: 'Nenne Vor- und Nachteile von Unternehmenszusammenschlüssen.',
    antwort: 'Vorteile: Synergieeffekte (Ressourcen, Know-how, Technologie), Zugang zu neuen Märkten oder Kundengruppen, Kostenvorteile durch Skaleneffekte, mehr Verhandlungsmacht.\nNachteile: Integrationsprobleme (unterschiedliche Unternehmenskulturen), Marktkonzentration bis hin zu Monopolen oder Oligopolen, hohe Kosten für Übernahme bzw. Fusion, steuerliche, rechtliche und organisatorische Komplexität.' },
  { id: 'vwl-rf-20', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2021): Erkläre das Kartell und das Joint Venture. Welchen Vorteil bietet ein Joint Venture einem Automobilzulieferer?',
    antwort: 'Kartell: Kooperation von zwei oder mehr Unternehmen, die Teilbereiche (v. a. des Absatzes wie Preise, Liefer- oder Auftragsbedingungen) absprechen. Die rechtliche Selbstständigkeit bleibt, die wirtschaftliche wird im Bereich der Absprachen aufgegeben.\nJoint Venture: Rechtlich und wirtschaftlich selbstständige Unternehmen gründen ein gemeinsames Tochterunternehmen, um Synergien zu nutzen, z. B. Know-how bei Batterien für Elektroautos.\nVorteil: Das Risiko des Scheiterns wird geteilt. In staatlich gelenkten Ländern ist ein Joint Venture teils Voraussetzung für den Marktzugang.' },
  { id: 'vwl-rf-21', fach: 'vwl', thema: 'Unternehmenszusammenschlüsse', typ: 'mc',
    frage: 'Welche Aussage zum Franchising stimmt?',
    optionen: ['Der Franchisenehmer ist rechtlich selbstständig und trägt das unternehmerische Risiko, ist aber an die Vorgaben des Franchisegebers gebunden', 'Der Franchisenehmer ist Angestellter des Franchisegebers', 'Franchising ist eine Fusion zweier Unternehmen', 'Der Franchisegeber haftet für alle Schulden des Franchisenehmers'],
    richtig: 0,
    erklaerung: 'Franchising ist eine Kooperation: gemeinsame Marke und gemeinsames Erscheinungsbild, Konzept und Werbung vom Franchisegeber, meist exklusives Vertriebsrecht in einer Region. Beispiele: McDonald’s, OBI, NORDSEE.' },
  { id: 'vwl-rf-22', fach: 'vwl', thema: 'Betriebe', typ: 'karte',
    frage: 'Wann gilt eine Kapitalgesellschaft nach § 267 HGB als klein, mittelgroß oder groß?',
    antwort: 'Klein: Bilanzsumme bis 6 Mio. €, Umsatz bis 12 Mio. €, bis 50 Arbeitnehmer.\nMittelgroß: bis 20 Mio. €, bis 40 Mio. €, bis 250 Arbeitnehmer.\nGroß: darüber.\nFür die nächsthöhere Klasse müssen mindestens 2 von 3 Merkmalen überschritten sein.' },
  { id: 'vwl-rf-23', fach: 'vwl', thema: 'Betriebe', typ: 'mc',
    frage: 'Zu welchem Wirtschaftssektor gehört eine Schreinerei?',
    optionen: ['Sekundärer Sektor', 'Primärer Sektor', 'Tertiärer Sektor', 'Quartärer Sektor'],
    richtig: 0,
    erklaerung: 'Primär = Urproduktion (Land-, Forstwirtschaft, Fischerei). Sekundär = Industrie und Handwerk (Verarbeitung). Tertiär = Dienstleistungen. Deutschland ist überwiegend im tertiären Sektor tätig.' },
  { id: 'vwl-rf-24', fach: 'vwl', thema: 'Betriebe', typ: 'karte',
    frage: 'Was kennzeichnet arbeits-, kapital- und materialintensive Betriebe?',
    antwort: 'Arbeitsintensiv: hoher Lohnkostenanteil (z. B. Handel, Dienstleistung, Handwerk).\nAnlagen- bzw. kapitalintensiv: viele Maschinen und Anlagen, hohe Kapitalbindung, weniger flexibel. Die Anlagen müssen ausgelastet werden (Massenproduktion).\nMaterialintensiv: Werkstoff- und Rohstoffkosten überdurchschnittlich hoch. Ein effizienter Materialeinsatz entscheidet über die Wettbewerbsfähigkeit.\nViele Betriebe sind Mischformen. Entscheidend ist der dominierende Faktor.' },
  { id: 'vwl-rf-25', fach: 'vwl', thema: 'Standortwahl', typ: 'mc',
    frage: 'Ein Kohlebergwerk ist ein Beispiel für einen …',
    optionen: ['gebundenen Standort', 'freien Standort', 'absatzorientierten Standort', 'virtuellen Standort'],
    richtig: 0,
    erklaerung: 'Gebundener Standort: durch natürliche Ressourcen oder Infrastruktur festgelegt (Abbau-, Energiebetriebe). Beim freien Standort wird nach ökonomischen Kriterien gewählt, dort ist eine systematische Standortanalyse nötig.' },
  { id: 'vwl-rf-26', fach: 'vwl', thema: 'Standortwahl', typ: 'karte',
    frage: 'Wie läuft eine Standortanalyse mit der Nutzwertanalyse ab?',
    antwort: '1. Relevante Standortfaktoren festlegen\n2. Faktoren gewichten (Summe der Gewichte = 1)\n3. Jede Alternative je Faktor bewerten (z. B. 1–10) = einfacher Nutzwert\n4. Gewichteter Nutzwert = einfacher Nutzwert × Gewicht\n5. Gewichtete Nutzwerte je Standort addieren\n6. Der Standort mit der höchsten Nutzwertsumme wird gewählt' },
  { id: 'vwl-rf-27', fach: 'vwl', thema: 'Standortwahl', typ: 'mc',
    frage: 'Nutzwertanalyse: Lohnniveau hat die Gewichtung 0,3. Standort A erhält dort 8 Punkte. Wie hoch ist der gewichtete Nutzwert?',
    optionen: ['2,4', '8,3', '0,24', '24'],
    richtig: 0,
    erklaerung: 'Gewichteter Nutzwert = einfacher Nutzwert × Gewicht = 8 × 0,3 = 2,4.' },
  { id: 'vwl-rf-28', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2022): Ein exportstarker Gerätehersteller sucht einen neuen Standort. Nenne vier Standortfaktoren und erläutere drei davon.',
    antwort: 'Faktoren: Absatzorientierung, Materialorientierung, Arbeitskräfte, Verkehr, Energie, Umwelt, Abgaben, digitale Infrastruktur.\nAbsatzorientierung: kurze Wege zum Kunden.\nVerkehr: Die Infrastruktur ist für Produktion und Export notwendig.\nArbeitskräfte: Facharbeiter für die Produktion und Ingenieure für die Weiterentwicklung müssen verfügbar sein.' },
  { id: 'vwl-rf-29', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (F2019): Nenne je drei Vor- und Nachteile des Standortes Deutschland.',
    antwort: 'Vorteile: vielseitige Wirtschaftsstruktur, gute Ausbildung, hohe Kaufkraft, gut ausgebaute Infrastruktur und zentrale Lage in Europa, sozialer Frieden, hohe Arbeitsproduktivität.\nNachteile: hohe Lohnnebenkosten, Bürokratie und hohe Verwaltungskosten, komplizierte Gesetze und hohe Steuern, wenig Wagniskapital, strenge Umweltvorschriften, strenges Arbeitsrecht.' },
  { id: 'vwl-rf-30', fach: 'vwl', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2018): Nenne Gründe (außer Personalkosten) für eine Produktionsverlagerung ins Ausland.',
    antwort: 'Neue Märkte erschließen: Präsenz vor Ort, Kundenwünsche früher erkennen.\nWährungsrisiken reduzieren (Produktion im Währungsraum des Absatzmarktes).\nKostengünstiger produzieren, z. B. durch geringere Arbeits- und Umweltschutzauflagen.\nInländische Arbeitsplätze sichern, die sonst durch Verlust der Wettbewerbsfähigkeit wegfallen würden.\nHandelsbeschränkungen (Zöllen) zuvorkommen.' },
);
